class SemanticRoutingError(ValueError):
    """Raised when semantic routing inputs or model output violate the contract."""


ModelRunner = Callable[[str, str, int], str]


def _clean_text(value: object, max_chars: int) -> str:
    clean, _ = redact_text(value)
    clean = clean.strip()
    if len(clean) <= max_chars:
        return clean
    return clean[: max(1, max_chars - 1)] + "…"


def _route_state_from_messages(messages: list[dict[str, Any]]) -> dict[str, Any]:
    for message in reversed(messages):
        if message.get("role") != "user":
            continue
        routing = message.get("routing")
        if not isinstance(routing, dict):
            continue
        active = routing.get("active_owner")
        if not isinstance(active, dict):
            skill = str(routing.get("skill") or "")
            if routing.get("decision") == "direct" and skill and skill != "wb-chat":
                active = {
                    "skill": skill,
                    "mode": routing.get("mode"),
                    "workflow": routing.get("workflow"),
                }
            else:
                active = None
        pending = routing.get("pending_handoff")
        return {
            "active_owner": active if isinstance(active, dict) else None,
            "pending_handoff": pending if isinstance(pending, dict) else None,
            "interaction_mode": (
                routing.get("interaction_mode")
                if routing.get("interaction_mode") in INTERACTION_MODES
                else None
            ),
        }
    return {
        "active_owner": None,
        "pending_handoff": None,
        "interaction_mode": None,
    }


def infer_interaction_mode(text: str, previous: str | None = None) -> str | None:
    lowered = normalize_phrase(text)
    if any(
        phrase in lowered
        for phrase in (
            "不要修改",
            "先不要改",
            "只读",
            "review mode",
            "审查",
            "确认下",
        )
    ):
        return "review-only"
    if any(
        phrase in lowered
        for phrase in ("discovery mode", "只看现状", "先调研", "梳理现状")
    ):
        return "discovery-only"
    conditional_execution = any(
        phrase in lowered
        for phrase in ("是否需要", "要不要", "是否应该", "值不值得")
    )
    explicit_followup_execution = any(
        phrase in lowered
        for phrase in ("并修复", "然后修复", "再修复", "直接修复", "分析后修复")
    )
    if conditional_execution and not explicit_followup_execution:
        return "review-only"
    if any(phrase in lowered for phrase in PROPOSAL_SIGNALS):
        if not any(phrase in lowered for phrase in STRONG_EXECUTION_SIGNALS):
            return "proposal-only"
    if any(phrase in lowered for phrase in EXECUTION_SIGNALS):
        return "execution"
    return previous if previous in INTERACTION_MODES else None


def _recent_messages(
    messages: list[dict[str, Any]],
    *,
    maximum: int,
    max_chars: int,
) -> list[dict[str, str]]:
    result: list[dict[str, str]] = []
    for message in messages[-maximum:]:
        role = str(message.get("role") or "")
        if role not in {"user", "assistant"}:
            continue
        content = _clean_text(message.get("content"), max_chars)
        if content:
            result.append({"role": role, "content": content})
    return result


def _parse_record_time(value: object) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _recent_task_records(
    project_id: str | None,
    *,
    history_root: Path,
    maximum: int,
    max_age_days: int,
    max_chars: int,
) -> list[dict[str, Any]]:
    if not project_id or not PROJECT_ID_RE.fullmatch(project_id):
        return []
    project_root = history_root / project_id
    if not project_root.is_dir():
        return []
    now = datetime.now().astimezone()
    cutoff = now.astimezone(timezone.utc) - timedelta(days=max_age_days)
    result: list[dict[str, Any]] = []
    date_paths = [
        project_root / (now.date() - timedelta(days=offset)).isoformat()
        for offset in range(max_age_days + 1)
    ]
    for date_path in date_paths:
        for path in sorted(date_path.glob("*.json"), reverse=True):
            if len(result) >= maximum:
                return result
            try:
                payload = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            if not isinstance(payload, dict):
                continue
            updated = _parse_record_time(
                payload.get("updated_at") or payload.get("created_at")
            )
            if updated is not None and updated < cutoff:
                continue
            assessment = payload.get("agent_assessment")
            execution = payload.get("execution_result")
            assessment = assessment if isinstance(assessment, dict) else {}
            execution = execution if isinstance(execution, dict) else {}
            expectation = payload.get("expectation")
            expectation = expectation if isinstance(expectation, dict) else {}
            expectation_assessment = expectation.get("assessment")
            expectation_assessment = (
                expectation_assessment
                if isinstance(expectation_assessment, dict)
                else {}
            )
            routing = payload.get("routing_trace")
            routing = routing if isinstance(routing, dict) else {}
            final_owner = routing.get("final_owner")
            final_owner = final_owner if isinstance(final_owner, dict) else {}
            route_entries = routing.get("entries")
            route_entries = route_entries if isinstance(route_entries, list) else []
            last_route = (
                route_entries[-1]
                if route_entries and isinstance(route_entries[-1], dict)
                else {}
            )
            feedback = payload.get("user_feedback")
            feedback = feedback if isinstance(feedback, dict) else {}
            learning = payload.get("learning_signal")
            learning = learning if isinstance(learning, dict) else {}
            row = {
                "task_id": _clean_text(payload.get("task_id"), 96),
                "title": _clean_text(payload.get("title"), max_chars),
                "goal": _clean_text(payload.get("goal"), max_chars),
                "expectation_summary": _clean_text(
                    expectation.get("summary"), max_chars
                ),
                "expectation_source": _clean_text(expectation.get("source"), 64),
                "expectation_status": _clean_text(
                    expectation_assessment.get("status"), 64
                ),
                "routing_status": _clean_text(routing.get("status"), 64),
                "final_owner_skill": _clean_text(final_owner.get("skill"), 96),
                "router_source": _clean_text(last_route.get("router_source"), 64),
                "match_type": _clean_text(last_route.get("match_type"), 96),
                "lifecycle_status": _clean_text(
                    payload.get("lifecycle_status"), 64
                ),
                "assessment_status": _clean_text(assessment.get("status"), 64),
                "effective_outcome": _clean_text(
                    TaskRecordCodec.effective_outcome(payload), 64
                ),
                "assessment_summary": _clean_text(
                    assessment.get("summary"), max_chars
                ),
                "result_summary": _clean_text(
                    execution.get("summary"), max_chars
                ),
                "feedback_status": _clean_text(feedback.get("status"), 64),
                "user_completion": _clean_text(feedback.get("completion"), 64),
                "user_satisfaction": _clean_text(
                    feedback.get("satisfaction"), 64
                ),
                "user_routing_quality": _clean_text(
                    feedback.get("routing_quality"), 64
                ),
                "learning_review": bool(learning.get("needs_review")),
                "learning_reasons": [
                    _clean_text(item, 160)
                    for item in learning.get("reasons") or []
                    if _clean_text(item, 160)
                ],
                "updated_at": _clean_text(payload.get("updated_at"), 64),
            }
            result.append({key: value for key, value in row.items() if value})
    return result


def _fit_context(payload: dict[str, Any], max_bytes: int) -> dict[str, Any]:
    payload = json.loads(json.dumps(payload, ensure_ascii=False))
    payload["context_truncated"] = False
    while (
        len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > max_bytes
        and payload.get("recent_tasks")
    ):
        payload["recent_tasks"].pop()
        payload["context_truncated"] = True
    while (
        len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) > max_bytes
        and payload.get("recent_messages")
    ):
        payload["recent_messages"].pop(0)
        payload["context_truncated"] = True
    return payload


def build_route_context(
    *,
    text: str,
    project_id: str | None,
    messages: list[dict[str, Any]],
    routing_config: dict[str, Any],
    history_root: Path = DEFAULT_HISTORY_ROOT,
) -> dict[str, Any]:
    policy = routing_config["_semantic_routing"]
    state = _route_state_from_messages(messages)
    interaction_mode = infer_interaction_mode(text, state.get("interaction_mode"))
    context = {
        "project_id": project_id,
        "interaction_mode": interaction_mode,
        "active_owner": state.get("active_owner"),
        "pending_handoff": state.get("pending_handoff"),
        "recent_messages": _recent_messages(
            messages,
            maximum=policy["max_history_messages"],
            max_chars=policy["max_message_chars"],
        ),
        "recent_tasks": _recent_task_records(
            project_id,
            history_root=history_root,
            maximum=policy["max_task_records"],
            max_age_days=policy["max_task_age_days"],
            max_chars=policy["max_message_chars"],
        ),
    }
    return _fit_context(context, policy["max_context_bytes"])


def available_skill_catalog(
    routing_config: dict[str, Any],
    available_skills: set[str],
) -> list[dict[str, Any]]:
    internal = routing_config["_internal_skills"]
    records = routing_config["_skill_records"]
    targets: dict[str, list[dict[str, Any]]] = {}
    seen_targets: dict[str, set[tuple[str | None, str | None]]] = {}
    for route in routing_config["routes"]:
        target = route["target"]
        skill = target["skill"]
        key = (target.get("mode"), target.get("workflow"))
        if key in seen_targets.setdefault(skill, set()):
            continue
        seen_targets[skill].add(key)
        targets.setdefault(skill, []).append(
            {"mode": target.get("mode"), "workflow": target.get("workflow")}
        )
    return [
        {
            "name": name,
            "project": records[name].get("project"),
            "description": records[name].get("description"),
            "canonical_targets": targets.get(name, []),
        }
        for name in sorted(available_skills)
        if name in records and name not in internal
    ]


def render_semantic_prompt(
    *,
    text: str,
    context: dict[str, Any],
    routing_config: dict[str, Any],
    available_skills: set[str],
    prompt_path: Path = DEFAULT_PROMPT,
    schema_path: Path = DEFAULT_SCHEMA,
) -> str:
    template = prompt_path.read_text(encoding="utf-8")
    missing = sorted(item for item in PROMPT_PLACEHOLDERS if item not in template)
    if missing:
        raise SemanticRoutingError(
            "semantic routing prompt 缺少 placeholder: " + ", ".join(missing)
        )
    schema = json.loads(schema_path.read_text(encoding="utf-8"))
    policy = routing_config["_semantic_routing"]
    clean_input = _clean_text(text, policy["max_context_bytes"])
    replacements = {
        "{{AVAILABLE_SKILLS_JSON}}": json.dumps(
            available_skill_catalog(routing_config, available_skills),
            ensure_ascii=False,
            indent=2,
        ),
        "{{ROUTE_CONTEXT_JSON}}": json.dumps(context, ensure_ascii=False, indent=2),
        "{{ROUTING_POLICY_JSON}}": json.dumps(
            {
                "model_accept_threshold": policy["model_accept_threshold"],
                "minimum_margin": policy["minimum_margin"],
                "zero_false_positive_skills": sorted(
                    _high_risk_skills(routing_config)
                ),
            },
            ensure_ascii=False,
            indent=2,
        ),
        "{{USER_INPUT_JSON}}": json.dumps(clean_input, ensure_ascii=False),
        "{{OUTPUT_SCHEMA_JSON}}": json.dumps(schema, ensure_ascii=False, indent=2),
    }
    for placeholder, value in replacements.items():
        template = template.replace(placeholder, value)
    return template


def run_semantic_model(
    prompt: str,
    stage: str,
    timeout_seconds: int,
    *,
    runner_path: Path = DEFAULT_MODEL_RUNNER,
) -> str:
    process = subprocess.Popen(
        ["bash", str(runner_path), "--stage", stage],
        cwd=WB_ROOT,
        text=True,
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        start_new_session=True,
    )
    try:
        stdout, _ = process.communicate(input=prompt, timeout=timeout_seconds)
    except subprocess.TimeoutExpired as exc:
        os.killpg(process.pid, signal.SIGTERM)
        try:
            process.communicate(timeout=5)
        except subprocess.TimeoutExpired:
            os.killpg(process.pid, signal.SIGKILL)
            process.communicate()
        raise SemanticRoutingError("semantic routing model timeout") from exc
    if process.returncode != 0:
        raise SemanticRoutingError("semantic routing model failed")
    if not stdout.strip():
        raise SemanticRoutingError("semantic routing model returned empty output")
    return stdout


def _json_object(raw: str) -> dict[str, Any]:
    candidate = raw.strip()
    fenced = re.fullmatch(
        r"```(?:json)?\s*(.*?)\s*```",
        candidate,
        flags=re.DOTALL | re.IGNORECASE,
    )
    if fenced:
        candidate = fenced.group(1).strip()
    try:
        payload = json.loads(candidate)
    except json.JSONDecodeError as exc:
        raise SemanticRoutingError("semantic routing model output is not JSON") from exc
    if not isinstance(payload, dict):
        raise SemanticRoutingError("semantic routing model output must be an object")
    return payload


def _validate_candidate(
    value: object,
    *,
    label: str,
    allowed_skills: set[str],
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise SemanticRoutingError(f"{label} 必须是 object")
    required = {"skill", "score", "mode", "workflow"}
    if set(value) != required:
        raise SemanticRoutingError(f"{label} 字段必须精确为 {sorted(required)}")
    skill = value.get("skill")
    if not isinstance(skill, str) or skill not in allowed_skills:
        raise SemanticRoutingError(f"{label}.skill 不在当前加载面")
    score = value.get("score")
    if (
        not isinstance(score, (int, float))
        or isinstance(score, bool)
        or not 0 <= float(score) <= 1
    ):
        raise SemanticRoutingError(f"{label}.score 必须在 [0, 1] 范围内")
    for key in ("mode", "workflow"):
        if value.get(key) is not None and not isinstance(value.get(key), str):
            raise SemanticRoutingError(f"{label}.{key} 必须是 string 或 null")
        if isinstance(value.get(key), str) and len(value[key]) > 80:
            raise SemanticRoutingError(f"{label}.{key} 最多 80 个字符")
    if value.get("mode") in INTERACTION_MODES:
        raise SemanticRoutingError(
            f"{label}.mode 不得使用 interaction_mode；应使用领域 mode 或 null"
        )
    return {
        "skill": skill,
        "score": float(score),
        "mode": value.get("mode"),
        "workflow": value.get("workflow"),
    }


def validate_model_result(
    payload: dict[str, Any],
    *,
    available_skills: set[str],
    internal_skills: set[str],
) -> dict[str, Any]:
    required = {
        "schema_version",
        "decision",
        "complexity",
        "interaction_mode",
        "primary",
        "alternatives",
        "needs_clarification",
        "clarification_question",
        "missing_context",
        "pending_handoff",
        "reason_codes",
    }
    if set(payload) != required:
        raise SemanticRoutingError(
            "semantic routing result 字段必须精确为 " + ", ".join(sorted(required))
        )
    if payload.get("schema_version") != 1:
        raise SemanticRoutingError("semantic routing result schema_version 必须为 1")
    decision = payload.get("decision")
    if decision not in {"answer", "route", "clarify"}:
        raise SemanticRoutingError("semantic routing result decision 无效")
    if payload.get("complexity") not in {"simple", "complex"}:
        raise SemanticRoutingError("semantic routing result complexity 无效")
    mode = payload.get("interaction_mode")
    if mode is not None and mode not in INTERACTION_MODES:
        raise SemanticRoutingError("semantic routing result interaction_mode 无效")
    allowed = set(available_skills) - set(internal_skills)
    primary = _validate_candidate(
        payload.get("primary"),
        label="primary",
        allowed_skills=allowed,
    )
    alternatives_raw = payload.get("alternatives")
    if not isinstance(alternatives_raw, list) or len(alternatives_raw) > 3:
        raise SemanticRoutingError("alternatives 必须是最多 3 项的 array")
    alternatives = [
        _validate_candidate(item, label=f"alternatives[{index}]", allowed_skills=allowed)
        for index, item in enumerate(alternatives_raw)
    ]
    candidate_skills = [primary["skill"], *(item["skill"] for item in alternatives)]
    if len(candidate_skills) != len(set(candidate_skills)):
        raise SemanticRoutingError("primary 与 alternatives 的 skill 不得重复")
    needs_clarification = payload.get("needs_clarification")
    if not isinstance(needs_clarification, bool):
        raise SemanticRoutingError("needs_clarification 必须是 boolean")
    question = payload.get("clarification_question")
    if question is not None and not isinstance(question, str):
        raise SemanticRoutingError("clarification_question 必须是 string 或 null")
    if isinstance(question, str) and len(question) > 500:
        raise SemanticRoutingError("clarification_question 最多 500 个字符")
    missing_context = payload.get("missing_context")
    if not isinstance(missing_context, list) or not all(
        isinstance(item, str) and item.strip() for item in missing_context
    ):
        raise SemanticRoutingError("missing_context 必须是非空 string 组成的 array")
    if len(missing_context) > 5 or any(len(item) > 200 for item in missing_context):
        raise SemanticRoutingError("missing_context 最多 5 项且每项最多 200 个字符")
    reason_codes = payload.get("reason_codes")
    if not isinstance(reason_codes, list) or not reason_codes or not all(
        isinstance(item, str) and REASON_CODE_RE.fullmatch(item)
        for item in reason_codes
    ):
        raise SemanticRoutingError("reason_codes 必须是合法的非空 string array")
    if len(reason_codes) > 10 or any(len(item) > 64 for item in reason_codes):
        raise SemanticRoutingError("reason_codes 最多 10 项且每项最多 64 个字符")
    if decision == "answer":
        if primary["skill"] != "wb-chat" or needs_clarification or question is not None:
            raise SemanticRoutingError("answer 必须由 wb-chat 承接且不追问")
    elif decision == "route":
        if primary["skill"] == "wb-chat" or needs_clarification or question is not None:
            raise SemanticRoutingError("route 必须选择非 wb-chat owner 且不追问")
        if missing_context:
            raise SemanticRoutingError("route 不得携带阻断性 missing_context")
    else:
        if not needs_clarification or not isinstance(question, str) or not question.strip():
            raise SemanticRoutingError("clarify 必须包含一个 clarification_question")

    pending = payload.get("pending_handoff")
    if pending is not None:
        if not isinstance(pending, dict):
            raise SemanticRoutingError("pending_handoff 必须是 object 或 null")
        pending_fields = {"skill", "mode", "workflow", "gate", "reason"}
        if set(pending) != pending_fields:
            raise SemanticRoutingError("pending_handoff 字段不符合契约")
        if pending.get("skill") not in allowed:
            raise SemanticRoutingError("pending_handoff.skill 不在当前加载面")
        if pending.get("gate") not in {"none", "confirmation", "explicit-request"}:
            raise SemanticRoutingError("pending_handoff.gate 无效")
        for key in ("mode", "workflow"):
            if pending.get(key) is not None and not isinstance(pending.get(key), str):
                raise SemanticRoutingError(f"pending_handoff.{key} 必须是 string 或 null")
            if isinstance(pending.get(key), str) and len(pending[key]) > 80:
                raise SemanticRoutingError(f"pending_handoff.{key} 最多 80 个字符")
        if pending.get("mode") in INTERACTION_MODES:
            raise SemanticRoutingError(
                "pending_handoff.mode 不得使用 interaction_mode"
            )
        if not isinstance(pending.get("reason"), str) or not pending["reason"].strip():
            raise SemanticRoutingError("pending_handoff.reason 不能为空")
        if len(pending["reason"]) > 500:
            raise SemanticRoutingError("pending_handoff.reason 最多 500 个字符")

    return {
        **payload,
        "primary": primary,
        "alternatives": alternatives,
        "missing_context": [item.strip() for item in missing_context],
        "reason_codes": list(reason_codes),
    }


def parse_model_result(
    raw: str,
    *,
    available_skills: set[str],
    internal_skills: set[str],
) -> dict[str, Any]:
    return validate_model_result(
        _json_object(raw),
        available_skills=available_skills,
        internal_skills=internal_skills,
    )


def _contains_any(text: str, values: set[str]) -> bool:
    lowered = normalize_phrase(text)
    return any(value in lowered for value in values)


def _is_confirmation(text: str) -> bool:
    normalized = normalize_phrase(text)
    return normalized in CONFIRMATION_PHRASES or any(
        phrase in normalized for phrase in ("按上面的", "按照上面的", "同意这个方案")
    )


def _is_continuation(text: str) -> bool:
    return normalize_phrase(text) in CONTINUATION_PHRASES


def _is_lightweight_answer(text: str) -> bool:
    normalized = normalize_phrase(text)
    if normalized in CASUAL_PHRASES:
        return True
    if (
        WORKBENCH_SKILL_RE.search(normalized)
        and _contains_any(normalized, WORKBENCH_META_SIGNALS)
        and not _contains_any(normalized, EXECUTION_SIGNALS)
        and not any(
            value in normalized for value in ("报错", "异常", "失败", "为什么")
        )
    ):
        return True
    if not LIGHTWEIGHT_QUESTION_RE.search(normalized):
        return False
    if _contains_any(normalized, REPOSITORY_SIGNALS | CURRENT_EXTERNAL_SIGNALS):
        return False
    return True


def _explicit_high_risk_signal(skill: str, text: str) -> bool:
    normalized = normalize_phrase(text)
    if skill == "wb-git":
        if any(
            value in normalized
            for value in (
                "git",
                "commit",
                "暂存",
                "分支",
                "cherry-pick",
                "rebase",
            )
        ):
            return True
        return "提交" in normalized and any(
            value in normalized for value in ("改动", "代码", "文件", "仓库")
        )
    if skill == "wb-session":
        has_domain = any(
            value in normalized
            for value in (
                "会话",
                "session",
                "tmux",
                "profile",
                "daemon",
                "sn-cli",
                "turn",
            )
        )
        has_operation = any(
            value in normalized
            for value in (
                "状态",
                "日志",
                "停止",
                "恢复",
                "卡",
                "运行",
                "查看",
                "健康",
            )
        )
        return has_domain and has_operation
    return False


def _high_risk_skills(routing_config: dict[str, Any]) -> set[str]:
    return set(
        routing_config["quality_gate"].get("zero_false_positive_skills", [])
    )


def _active_owner_can_continue(
    active: dict[str, Any],
    *,
    text: str,
    interaction_mode: str | None,
    high_risk_skills: set[str],
) -> bool:
    skill = str(active.get("skill") or "")
    if not skill or not (_is_continuation(text) or _is_confirmation(text)):
        return False
    if skill in high_risk_skills and not _explicit_high_risk_signal(skill, text):
        return False
    if interaction_mode == "execution" and skill in {
        "wb-chat",
        "wb-repo",
        "wb-design",
        "wb-research",
        "wb-knowledge",
        "wb-learning",
    }:
        return False
    return True


def _pending_can_handoff(
    pending: dict[str, Any],
    *,
    text: str,
    high_risk_skills: set[str],
) -> bool:
    skill = str(pending.get("skill") or "")
    if not skill:
        return False
    gate = pending.get("gate")
    if skill in high_risk_skills:
        return _explicit_high_risk_signal(skill, text)
    if skill in WRITE_OWNER_SKILLS:
        return _contains_any(text, EXECUTION_SIGNALS)
    if gate == "explicit-request":
        return _contains_any(text, EXECUTION_SIGNALS)
    return gate == "none" or _is_confirmation(text)


def _owner_payload(candidate: dict[str, Any]) -> dict[str, Any]:
    return {
        "skill": candidate["skill"],
        "mode": candidate.get("mode"),
        "workflow": candidate.get("workflow"),
    }


def _direct_result(
    candidate: dict[str, Any],
    *,
    source: str,
    match_type: str,
    confidence: float,
    margin: float,
    complexity: str,
    interaction_mode: str | None,
    runner_up: dict[str, Any] | None = None,
    pending_handoff: dict[str, Any] | None = None,
    reason_codes: list[str] | None = None,
) -> dict[str, Any]:
    result = {
        "decision": "direct",
        "skill": candidate["skill"],
        "mode": candidate.get("mode"),
        "workflow": candidate.get("workflow"),
        "match_type": match_type,
        "router_source": source,
        "confidence": round(float(confidence), 6),
        "margin": round(float(margin), 6),
        "complexity": complexity,
        "interaction_mode": interaction_mode,
        "active_owner": _owner_payload(candidate),
        "pending_handoff": pending_handoff,
        "reason_codes": reason_codes or [match_type],
        "reason": "语义候选通过 score、margin、scope、授权与风险门禁",
    }
    if runner_up is not None:
        result["runner_up"] = runner_up
    return result


def _chat_result(
    *,
    mode: str,
    source: str,
    match_type: str,
    complexity: str,
    interaction_mode: str | None,
    active_owner: dict[str, Any] | None,
    pending_handoff: dict[str, Any] | None = None,
    confidence: float | None = None,
    margin: float | None = None,
    runner_up: dict[str, Any] | None = None,
    clarification_question: str | None = None,
    missing_context: list[str] | None = None,
    reason_codes: list[str] | None = None,
    reason: str,
) -> dict[str, Any]:
    result: dict[str, Any] = {
        "decision": "chat",
        "skill": "wb-chat",
        "mode": mode,
        "match_type": match_type,
        "router_source": source,
        "complexity": complexity,
        "interaction_mode": interaction_mode,
        "active_owner": active_owner,
        "pending_handoff": pending_handoff,
        "missing_context": missing_context or [],
        "reason_codes": reason_codes or [match_type],
        "reason": reason,
    }
    if confidence is not None:
        result["confidence"] = round(float(confidence), 6)
    if margin is not None:
        result["margin"] = round(float(margin), 6)
    if runner_up is not None:
        result["runner_up"] = runner_up
    if clarification_question:
        result["clarification_question"] = clarification_question
    return result


def _complexity(text: str) -> tuple[str, list[str]]:
    normalized = normalize_phrase(text)
    codes: list[str] = []
    owner_signal_groups = [
        REPOSITORY_SIGNALS,
        EXECUTION_SIGNALS,
        PROPOSAL_SIGNALS,
        HIGH_RISK_SIGNALS["wb-git"],
        HIGH_RISK_SIGNALS["wb-session"],
    ]
    group_count = sum(1 for values in owner_signal_groups if _contains_any(normalized, values))
    if group_count >= 2:
        codes.append("multi-owner-signals")
    if any(value in normalized for value in ("先", "再", "然后", "同时", "以及", "并且")):
        codes.append("multi-step")
    if _contains_any(normalized, PROPOSAL_SIGNALS) and _contains_any(
        normalized, STRONG_EXECUTION_SIGNALS
    ):
        codes.append("mixed-proposal-execution")
    if any(value in normalized for value in ("规则", "长期", "owner", "scope", "权限")):
        codes.append("governance-change")
    return ("complex" if codes else "simple"), codes


def _similarity_candidate(
    text: str,
    routing_config: dict[str, Any],
    available_skills: set[str],
) -> tuple[dict[str, Any] | None, float, dict[str, Any] | None, float]:
    normalized = normalize_phrase(text)
    by_skill: dict[str, tuple[float, dict[str, Any]]] = {}
    high_risk = _high_risk_skills(routing_config)
    for route in routing_config["routes"]:
        target = route["target"]
        skill = target["skill"]
        if skill not in available_skills or skill in high_risk:
            continue
        score = max(
            SequenceMatcher(None, normalized, normalize_phrase(phrase)).ratio()
            for phrase in route["exact_phrases"]
        )
        if skill not in by_skill or score > by_skill[skill][0]:
            by_skill[skill] = (
                score,
                {
                    "skill": skill,
                    "mode": target.get("mode"),
                    "workflow": target.get("workflow"),
                },
            )
    ranked = sorted(
        ((score, candidate) for score, candidate in by_skill.values()),
        key=lambda item: (-item[0], item[1]["skill"]),
    )
    if not ranked:
        return None, 0.0, None, 0.0
    top_score, top = ranked[0]
    if len(ranked) == 1:
        return top, top_score, None, 0.0
    runner_score, runner = ranked[1]
    return top, top_score, runner, runner_score


def _self_route(
    text: str,
    *,
    context: dict[str, Any],
    routing_config: dict[str, Any],
    available_skills: set[str],
) -> dict[str, Any] | None:
    policy = routing_config["_semantic_routing"]
    high_risk = _high_risk_skills(routing_config)
    active = context.get("active_owner")
    pending = context.get("pending_handoff")
    interaction_mode = context.get("interaction_mode")
    complexity, complexity_codes = _complexity(text)

    if (
        isinstance(active, dict)
        and active.get("skill") in available_skills
        and _is_continuation(text)
        and _active_owner_can_continue(
            active,
            text=text,
            interaction_mode=interaction_mode,
            high_risk_skills=high_risk,
        )
    ):
        return _direct_result(
            active,
            source="self",
            match_type="semantic-active-owner",
            confidence=1.0,
            margin=1.0,
            complexity=complexity,
            interaction_mode=interaction_mode,
            pending_handoff=pending,
            reason_codes=["active-owner-continuation", *complexity_codes],
        )

    if (
        isinstance(pending, dict)
        and pending.get("skill") in available_skills
        and _pending_can_handoff(pending, text=text, high_risk_skills=high_risk)
    ):
        return _direct_result(
            pending,
            source="self",
            match_type="semantic-pending-handoff",
            confidence=1.0,
            margin=1.0,
            complexity=complexity,
            interaction_mode=interaction_mode,
            reason_codes=["pending-handoff-confirmed", *complexity_codes],
        )

    if (
        not isinstance(pending, dict)
        and isinstance(active, dict)
        and active.get("skill") in available_skills
        and _active_owner_can_continue(
            active,
            text=text,
            interaction_mode=interaction_mode,
            high_risk_skills=high_risk,
        )
    ):
        return _direct_result(
            active,
            source="self",
            match_type="semantic-active-owner",
            confidence=1.0,
            margin=1.0,
            complexity=complexity,
            interaction_mode=interaction_mode,
            reason_codes=["active-owner-confirmed", *complexity_codes],
        )

    if _is_lightweight_answer(text) and not isinstance(pending, dict):
        return _chat_result(
            mode="answer",
            source="self",
            match_type="semantic-self-answer",
            complexity="simple",
            interaction_mode=interaction_mode,
            active_owner=None,
            confidence=1.0,
            margin=1.0,
            reason_codes=["lightweight-answer"],
            reason="日常对话或通用轻量问答由 wb-chat 直接承接",
        )

    candidate, score, runner, runner_score = _similarity_candidate(
        text,
        routing_config,
        available_skills,
    )
    margin = score - runner_score
    if (
        candidate is not None
        and complexity == "simple"
        and score >= float(policy["self_accept_threshold"])
        and margin >= float(policy["minimum_margin"])
    ):
        runner_up = (
            {"skill": runner["skill"], "score": round(runner_score, 6)}
            if runner is not None
            else None
        )
        return _direct_result(
            candidate,
            source="self",
            match_type="semantic-self-score",
            confidence=score,
            margin=margin,
            complexity=complexity,
            interaction_mode=interaction_mode,
            runner_up=runner_up,
            reason_codes=["local-semantic-score"],
        )
    return None


def route_locally(
    text: str,
    routing_config: dict[str, Any],
    *,
    project_id: str | None,
    available_skills: set[str],
) -> dict[str, Any] | None:
    """Run the history-independent self lane used before model dispatch."""

    context = {
        "project_id": project_id,
        "interaction_mode": infer_interaction_mode(text),
        "active_owner": None,
        "pending_handoff": None,
        "recent_messages": [],
        "recent_tasks": [],
        "context_truncated": False,
    }
    return _self_route(
        text,
        context=context,
        routing_config=routing_config,
        available_skills=available_skills,
    )


def _pending_from_model(
    result: dict[str, Any],
    *,
    high_risk_skills: set[str],
) -> dict[str, Any] | None:
    pending = result.get("pending_handoff")
    if result["decision"] == "clarify" and isinstance(pending, dict):
        return pending
    primary = result["primary"]
    if primary["skill"] == "wb-chat":
        return None
    return {
        "skill": primary["skill"],
        "mode": primary.get("mode"),
        "workflow": primary.get("workflow"),
        "gate": (
            "explicit-request"
            if primary["skill"] in high_risk_skills
            or primary["skill"] in WRITE_OWNER_SKILLS
            else "confirmation"
        ),
        "reason": "候选 owner 尚未通过全部接受门禁",
    }


def _route_model_result(
    result: dict[str, Any],
    *,
    text: str,
    context: dict[str, Any],
    routing_config: dict[str, Any],
) -> dict[str, Any]:
    policy = routing_config["_semantic_routing"]
    primary = result["primary"]
    alternatives = sorted(
        result["alternatives"], key=lambda item: item["score"], reverse=True
    )
    runner = alternatives[0] if alternatives else None
    runner_score = runner["score"] if runner else 0.0
    margin = primary["score"] - runner_score
    runner_up = (
        {"skill": runner["skill"], "score": round(runner_score, 6)}
        if runner is not None
        else None
    )
    high_risk = _high_risk_skills(routing_config)
    # 当前输入和既有只读授权是事实源，模型只能在本地未识别时补充，不能升级授权。
    interaction_mode = context.get("interaction_mode") or result.get("interaction_mode")
    can_accept = (
        result["decision"] == "route"
        and primary["score"] >= float(policy["model_accept_threshold"])
        and margin >= float(policy["minimum_margin"])
        and not result["missing_context"]
        and not result["needs_clarification"]
    )
    if interaction_mode != "execution" and (
        primary["skill"] in WRITE_OWNER_SKILLS
        or primary.get("mode") in WRITE_MODES
    ):
        can_accept = False
    if primary["skill"] in high_risk and not _explicit_high_risk_signal(
        primary["skill"], text
    ):
        can_accept = False
    if can_accept:
        return _direct_result(
            primary,
            source="cx-adv",
            match_type="semantic-model",
            confidence=primary["score"],
            margin=margin,
            complexity=result["complexity"],
            interaction_mode=interaction_mode,
            runner_up=runner_up,
            pending_handoff=(
                result.get("pending_handoff")
                if isinstance(result.get("pending_handoff"), dict)
                else None
            ),
            reason_codes=result["reason_codes"],
        )

    if (
        result["decision"] == "answer"
        and primary["skill"] == "wb-chat"
        and primary["score"] >= float(policy["model_accept_threshold"])
        and margin >= float(policy["minimum_margin"])
        and not result["missing_context"]
    ):
        return _chat_result(
            mode="answer",
            source="cx-adv",
            match_type="semantic-model-answer",
            complexity=result["complexity"],
            interaction_mode=interaction_mode,
            active_owner=None,
            confidence=primary["score"],
            margin=margin,
            runner_up=runner_up,
            reason_codes=result["reason_codes"],
            reason="模型判定为 wb-chat 可直接承接的轻量问答",
        )

    pending = _pending_from_model(result, high_risk_skills=high_risk)
    question = result.get("clarification_question")
    if not question and pending:
        if pending["gate"] == "explicit-request":
            question = f"请明确说明是否要执行 {pending['skill']} 对应的操作。"
        else:
            question = f"是否按 {pending['skill']} 作为本轮唯一 owner 继续？"
    return _chat_result(
        mode="clarify",
        source="cx-adv",
        match_type="semantic-model-clarify",
        complexity=result["complexity"],
        interaction_mode=interaction_mode,
        active_owner=context.get("active_owner"),
        pending_handoff=pending,
        confidence=primary["score"],
        margin=margin,
        runner_up=runner_up,
        clarification_question=question,
        missing_context=result["missing_context"],
        reason_codes=result["reason_codes"],
        reason="候选未通过 score、margin、上下文、授权或风险门禁",
    )


def route_semantically(
    text: str,
    routing_config: dict[str, Any],
    *,
    project_id: str | None,
    available_skills: set[str],
    messages: list[dict[str, Any]] | None = None,
    model_runner: ModelRunner | None = None,
    history_root: Path = DEFAULT_HISTORY_ROOT,
) -> dict[str, Any]:
    messages = list(messages or [])
    context = build_route_context(
        text=text,
        project_id=project_id,
        messages=messages,
        routing_config=routing_config,
        history_root=history_root,
    )
    self_result = _self_route(
        text,
        context=context,
        routing_config=routing_config,
        available_skills=available_skills,
    )
    if self_result is not None:
        return self_result

    policy = routing_config["_semantic_routing"]
    complexity, complexity_codes = _complexity(text)
    if not policy["enabled"]:
        return _chat_result(
            mode="triage",
            source="disabled",
            match_type="semantic-disabled",
            complexity=complexity,
            interaction_mode=context.get("interaction_mode"),
            active_owner=context.get("active_owner"),
            pending_handoff=context.get("pending_handoff"),
            reason_codes=["semantic-routing-disabled", *complexity_codes],
            reason="语义路由已禁用，由 wb-chat 在当前会话内分流",
        )

    try:
        prompt = render_semantic_prompt(
            text=text,
            context=context,
            routing_config=routing_config,
            available_skills=available_skills,
        )
        runner = model_runner or run_semantic_model
        raw = runner(
            prompt,
            policy["stage"],
            policy["model_timeout_seconds"],
        )
        model_result = parse_model_result(
            raw,
            available_skills=available_skills,
            internal_skills=routing_config["_internal_skills"],
        )
        return _route_model_result(
            model_result,
            text=text,
            context=context,
            routing_config=routing_config,
        )
    except (SemanticRoutingError, OSError, subprocess.SubprocessError, json.JSONDecodeError):
        return _chat_result(
            mode="triage",
            source="cx-adv",
            match_type="semantic-model-fallback",
            complexity=complexity,
            interaction_mode=context.get("interaction_mode"),
            active_owner=context.get("active_owner"),
            pending_handoff=context.get("pending_handoff"),
            reason_codes=["semantic-model-unavailable", *complexity_codes],
            reason="语义模型失败、超时或输出无效；安全回退 wb-chat",
        )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="wb-chat context-aware semantic router")
    parser.add_argument("--config", default=str(DEFAULT_CONFIG))
    parser.add_argument("--index", default=str(DEFAULT_INDEX))
    parser.add_argument("--text", help="input text; omit to read stdin")
    parser.add_argument("--project", help="active project id; defaults to cwd inference")
    parser.add_argument("--print-prompt", action="store_true")
    parser.add_argument("--no-model", action="store_true")
    args = parser.parse_args(argv)
    try:
        config = load_config(
            Path(args.config).expanduser().resolve(),
            Path(args.index).expanduser().resolve(),
        )
        text = args.text if args.text is not None else sys.stdin.read()
        project_id = args.project or infer_project_from_path(Path.cwd())
        available = configured_available_skills(config, project_id=project_id)
        context = build_route_context(
            text=text,
            project_id=project_id,
            messages=[],
            routing_config=config,
        )
        if args.print_prompt:
            print(
                render_semantic_prompt(
                    text=text,
                    context=context,
                    routing_config=config,
                    available_skills=available,
                )
            )
            return 0
        if args.no_model:
            config["_semantic_routing"] = {
                **config["_semantic_routing"],
                "enabled": False,
            }
        print(
            json.dumps(
                route_semantically(
                    text,
                    config,
                    project_id=project_id,
                    available_skills=available,
                ),
                ensure_ascii=False,
                indent=2,
            )
        )
        return 0
    except (SemanticRoutingError, ValueError, OSError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

