#!/usr/bin/env python3
"""Deterministic Workbench fast router for explicit skills and exact aliases."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
import re
import sys
import unicodedata
from typing import Any

from wb.workspace.project_scope import infer_project_from_path
from wb.workspace.config_layers import load_document
from wb.workspace.paths import WB_ROOT
from wb.agent.skill_projection import develop_mode_enabled


DEFAULT_CONFIG = WB_ROOT / "apps" / "agent" / "conf" / "skill-routing.yaml"
DEFAULT_INDEX = WB_ROOT / "skills" / "index.json"
EXPLICIT_SKILL_RE = re.compile(r"\$([A-Za-z0-9][A-Za-z0-9._-]*)")
MODEL_STAGE_RE = re.compile(r"^[a-z0-9][a-z0-9-]*\.[a-z0-9][a-z0-9_]*$")
TERMINAL_PUNCTUATION_RE = re.compile(r"[。！？!?；;，,、.]+$")


class RoutingConfigError(ValueError):
    """Raised when the deterministic routing config is invalid."""


def normalize_phrase(value: str) -> str:
    normalized = unicodedata.normalize("NFKC", value).casefold().strip()
    normalized = re.sub(r"\s+", " ", normalized)
    return TERMINAL_PUNCTUATION_RE.sub("", normalized).strip()


def _skill_records(
    index_path: Path,
) -> tuple[dict[str, dict[str, Any]], set[str], set[str], set[str]]:
    try:
        payload = json.loads(index_path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise RoutingConfigError(f"skill index 不存在: {index_path}") from exc
    except json.JSONDecodeError as exc:
        raise RoutingConfigError(f"skill index 不是合法 JSON: {index_path}: {exc}") from exc
    skills = payload.get("skills")
    if not isinstance(skills, list):
        raise RoutingConfigError(f"skill index 缺少 skills array: {index_path}")
    raw_global = payload.get("global_loadable_skills")
    if not isinstance(raw_global, list) or not all(isinstance(item, str) for item in raw_global):
        raise RoutingConfigError(f"skill index 缺少 global_loadable_skills array: {index_path}")
    raw_develop = payload.get("develop_loadable_skills")
    if not isinstance(raw_develop, list) or not all(
        isinstance(item, str) for item in raw_develop
    ):
        raise RoutingConfigError(f"skill index 缺少 develop_loadable_skills array: {index_path}")
    raw_internal = payload.get("internal_skills")
    if not isinstance(raw_internal, list) or not all(
        isinstance(item, str) for item in raw_internal
    ):
        raise RoutingConfigError(f"skill index 缺少 internal_skills array: {index_path}")
    records: dict[str, dict[str, Any]] = {}
    for item in skills:
        if not isinstance(item, dict) or not isinstance(item.get("name"), str):
            raise RoutingConfigError(f"skill index 包含无效记录: {index_path}")
        name = item["name"].strip()
        if not name or name in records:
            raise RoutingConfigError(f"skill index 包含空名称或重复名称: {name!r}")
        records[name] = item
    global_loadable = set(raw_global)
    develop_loadable = set(raw_develop)
    internal_skills = set(raw_internal)
    overlap = sorted(
        (global_loadable & develop_loadable)
        | (global_loadable & internal_skills)
        | (develop_loadable & internal_skills)
    )
    if overlap:
        raise RoutingConfigError(
            "skill index global/develop 加载面重叠: " + ", ".join(overlap)
        )
    unknown_global = sorted(global_loadable - records.keys())
    if unknown_global:
        raise RoutingConfigError(
            "skill index global_loadable_skills 包含未知 skill: "
            + ", ".join(unknown_global)
        )
    unknown_develop = sorted(develop_loadable - records.keys())
    if unknown_develop:
        raise RoutingConfigError(
            "skill index develop_loadable_skills 包含未知 skill: "
            + ", ".join(unknown_develop)
        )
    unknown_internal = sorted(internal_skills - records.keys())
    if unknown_internal:
        raise RoutingConfigError(
            "skill index internal_skills 包含未知 skill: "
            + ", ".join(unknown_internal)
        )
    return records, global_loadable, develop_loadable, internal_skills


def load_config(
    config_path: Path = DEFAULT_CONFIG,
    index_path: Path = DEFAULT_INDEX,
) -> dict[str, Any]:
    try:
        payload = load_document(config_path)
    except FileNotFoundError as exc:
        raise RoutingConfigError(f"路由配置不存在: {config_path}") from exc
    except (json.JSONDecodeError, ValueError) as exc:
        raise RoutingConfigError(f"路由配置无法解析: {config_path}: {exc}") from exc
    if not isinstance(payload, dict):
        raise RoutingConfigError("路由配置必须是 YAML object")

    (
        skill_records,
        global_loadable_skills,
        develop_loadable_skills,
        internal_skills,
    ) = _skill_records(index_path)
    routable_root_skills = global_loadable_skills | develop_loadable_skills
    known_skills = set(skill_records)
    fallback = payload.get("fallback_skill")
    if not isinstance(fallback, str) or fallback not in known_skills:
        raise RoutingConfigError(f"fallback_skill 未注册: {fallback!r}")
    if fallback not in global_loadable_skills:
        raise RoutingConfigError(f"fallback_skill 未进入全局加载面: {fallback}")

    semantic_only_skills = payload.get("semantic_only_skills", [])
    if not isinstance(semantic_only_skills, list) or not all(
        isinstance(item, str) for item in semantic_only_skills
    ):
        raise RoutingConfigError("semantic_only_skills 必须是 string array")
    if len(semantic_only_skills) != len(set(semantic_only_skills)):
        raise RoutingConfigError("semantic_only_skills 不得重复")
    semantic_only = set(semantic_only_skills)
    unknown_semantic = sorted(semantic_only - known_skills)
    if unknown_semantic:
        raise RoutingConfigError(f"semantic-only skill 未注册: {', '.join(unknown_semantic)}")
    invalid_semantic = sorted(semantic_only & (internal_skills | {fallback}))
    if invalid_semantic:
        raise RoutingConfigError(
            "semantic_only_skills 不得包含 fallback/internal skill: "
            + ", ".join(invalid_semantic)
        )
    unavailable_semantic = sorted(
        skill
        for skill in semantic_only
        if skill_records[skill].get("enabled", True) is True
        if not skill_records[skill].get("project")
        and skill not in routable_root_skills
    )
    if unavailable_semantic:
        raise RoutingConfigError(
            "semantic-only root skill 未进入 global/develop 加载面: "
            + ", ".join(unavailable_semantic)
        )

    quality_gate = payload.get("quality_gate")
    if not isinstance(quality_gate, dict):
        raise RoutingConfigError("quality_gate 必须是 JSON object")
    if quality_gate.get("metric") != "top1_owner_accuracy":
        raise RoutingConfigError("quality_gate.metric 必须是 top1_owner_accuracy")
    minimum = quality_gate.get("minimum")
    if not isinstance(minimum, (int, float)) or not 0 < float(minimum) <= 1:
        raise RoutingConfigError("quality_gate.minimum 必须在 (0, 1] 范围内")
    for key in (
        "minimum_accepted_precision",
        "minimum_coverage",
        "minimum_route_contract_accuracy",
    ):
        value = quality_gate.get(key)
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise RoutingConfigError(f"quality_gate.{key} 必须是 number")
        if not 0 < float(value) <= 1:
            raise RoutingConfigError(f"quality_gate.{key} 必须在 (0, 1] 范围内")
    if not isinstance(quality_gate.get("dataset"), str) or not quality_gate["dataset"]:
        raise RoutingConfigError("quality_gate.dataset 必须是非空路径")
    if not isinstance(quality_gate.get("semantic_predictions_required"), bool):
        raise RoutingConfigError("quality_gate.semantic_predictions_required 必须是 boolean")
    zero_false_positive = quality_gate.get("zero_false_positive_skills")
    if not isinstance(zero_false_positive, list) or not all(
        isinstance(item, str) for item in zero_false_positive
    ):
        raise RoutingConfigError("quality_gate.zero_false_positive_skills 必须是 string array")
    if len(zero_false_positive) != len(set(zero_false_positive)):
        raise RoutingConfigError("quality_gate.zero_false_positive_skills 不得重复")
    invalid_high_risk = sorted(set(zero_false_positive) - known_skills)
    if invalid_high_risk:
        raise RoutingConfigError(
            "quality_gate.zero_false_positive_skills 包含未注册 skill: "
            + ", ".join(invalid_high_risk)
        )

    semantic_routing = payload.get("semantic_routing")
    if not isinstance(semantic_routing, dict):
        raise RoutingConfigError("semantic_routing 必须是 YAML object")
    if not isinstance(semantic_routing.get("enabled"), bool):
        raise RoutingConfigError("semantic_routing.enabled 必须是 boolean")
    stage = semantic_routing.get("stage")
    if (
        not isinstance(stage, str)
        or not MODEL_STAGE_RE.fullmatch(stage)
        or not stage.startswith(f"{fallback}.")
    ):
        raise RoutingConfigError(
            f"semantic_routing.stage 必须是 {fallback}.<stage_name>"
        )
    for key in (
        "self_accept_threshold",
        "model_accept_threshold",
        "minimum_margin",
    ):
        value = semantic_routing.get(key)
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise RoutingConfigError(f"semantic_routing.{key} 必须是 number")
        if not 0 < float(value) <= 1:
            raise RoutingConfigError(f"semantic_routing.{key} 必须在 (0, 1] 范围内")
    for key in (
        "max_history_messages",
        "max_message_chars",
        "max_task_records",
        "max_task_age_days",
        "max_context_bytes",
        "model_timeout_seconds",
    ):
        value = semantic_routing.get(key)
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            raise RoutingConfigError(f"semantic_routing.{key} 必须是正整数")

    routes = payload.get("routes")
    if not isinstance(routes, list):
        raise RoutingConfigError("routes 必须是 array")
    aliases: dict[str, str] = {}
    route_ids: set[str] = set()
    targeted_skills: set[str] = set()
    for route in routes:
        if not isinstance(route, dict):
            raise RoutingConfigError("route 必须是 JSON object")
        route_id = route.get("id")
        target = route.get("target")
        phrases = route.get("exact_phrases")
        if not isinstance(route_id, str) or not route_id or route_id in route_ids:
            raise RoutingConfigError(f"route id 为空或重复: {route_id!r}")
        route_ids.add(route_id)
        if not isinstance(target, dict) or not isinstance(target.get("skill"), str):
            raise RoutingConfigError(f"route {route_id} 缺少 target.skill")
        skill = target["skill"]
        if skill not in known_skills:
            raise RoutingConfigError(f"route {route_id} 的 target skill 未注册: {skill}")
        if skill in internal_skills:
            raise RoutingConfigError(f"route {route_id} 不得直接映射内部 skill: {skill}")
        if (
            skill_records[skill].get("enabled", True) is True
            and not skill_records[skill].get("project")
            and skill not in routable_root_skills
        ):
            raise RoutingConfigError(
                f"route {route_id} 的 root target 未进入 global/develop 加载面: {skill}"
            )
        if skill_records[skill].get("enabled", True) is True:
            targeted_skills.add(skill)
        if not isinstance(phrases, list) or not phrases:
            raise RoutingConfigError(f"route {route_id} 的 exact_phrases 必须是非空 array")
        for phrase in phrases:
            if not isinstance(phrase, str) or not normalize_phrase(phrase):
                raise RoutingConfigError(f"route {route_id} 包含空短语")
            normalized = normalize_phrase(phrase)
            if normalized in aliases:
                raise RoutingConfigError(
                    f"归一化短语重复: {phrase!r} 同时属于 {aliases[normalized]} 和 {route_id}"
                )
            aliases[normalized] = route_id

    unmapped = sorted(
        {
            skill
            for skill in known_skills
            if skill_records[skill].get("enabled", True) is True
        }
        - targeted_skills
        - internal_skills
        - semantic_only
        - {fallback}
    )
    if unmapped:
        raise RoutingConfigError(f"用户可见 skill 缺少 exact phrase 映射: {', '.join(unmapped)}")

    payload["_known_skills"] = known_skills
    payload["_skill_records"] = skill_records
    payload["_global_loadable_skills"] = global_loadable_skills
    payload["_develop_loadable_skills"] = develop_loadable_skills
    payload["_internal_skills"] = internal_skills
    payload["_aliases"] = aliases
    payload["_semantic_routing"] = semantic_routing
    return payload


def configured_available_skills(
    config: dict[str, Any],
    *,
    project_id: str | None,
    include_develop: bool | None = None,
) -> set[str]:
    available = set(config["_global_loadable_skills"])
    develop_enabled = (
        develop_mode_enabled() if include_develop is None else include_develop
    )
    if develop_enabled:
        available.update(config["_develop_loadable_skills"])
    if project_id:
        available.update(
            name
            for name, record in config["_skill_records"].items()
            if record.get("enabled", True) is True
            and record.get("project") == project_id
        )
    return available


def _scope_mismatch_reason(
    skill: str,
    config: dict[str, Any],
    *,
    project_id: str | None,
    available_skills: set[str] | None,
) -> str | None:
    record = config["_skill_records"].get(skill, {})
    if record.get("enabled", True) is not True:
        return f"{skill} 已在 configs/skills.yaml 禁用"
    owned_project = str(record.get("project") or "").strip()
    if owned_project and project_id != owned_project:
        current = project_id or "未选择"
        return f"{skill} 仅属于 project={owned_project}，当前 project={current}"
    if available_skills is not None and skill not in available_skills:
        return f"当前 Agent 加载面缺少 {skill}"
    return None


def _scope_fallback(
    *,
    fallback: str,
    candidate_skill: str,
    match_type: str,
    reason: str,
    route_id: str | None = None,
) -> dict[str, Any]:
    result: dict[str, Any] = {
        "decision": "chat",
        "skill": fallback,
        "mode": "clarify",
        "match_type": match_type,
        "router_source": "deterministic",
        "candidate_skill": candidate_skill,
        "reason": reason,
    }
    if route_id:
        result["route_id"] = route_id
    return result


def route_text(
    text: str,
    config: dict[str, Any],
    *,
    project_id: str | None = None,
    available_skills: set[str] | None = None,
) -> dict[str, Any]:
    fallback = config["fallback_skill"]
    known_skills: set[str] = config["_known_skills"]
    dollar_tokens = set(EXPLICIT_SKILL_RE.findall(text))
    # `$HOME`、`$PATH` 等 shell 变量与真实 skill 共用 `$name` 语法。
    # 只有已登记名称才有资格进入显式 skill 路由，未知 token 留给正常语义层处理。
    explicit = sorted(dollar_tokens & known_skills)
    if explicit:
        if len(explicit) == 1:
            candidate = explicit[0]
            if candidate in config["_internal_skills"]:
                return _scope_fallback(
                    fallback=fallback,
                    candidate_skill=candidate,
                    match_type="explicit-skill-internal",
                    reason=f"{candidate} 是内部能力，只接受领域 owner 委托",
                )
            mismatch = _scope_mismatch_reason(
                candidate,
                config,
                project_id=project_id,
                available_skills=available_skills,
            )
            if mismatch:
                return _scope_fallback(
                    fallback=fallback,
                    candidate_skill=candidate,
                    match_type="explicit-skill-out-of-scope",
                    reason=mismatch,
                )
            return {
                "decision": "direct",
                "skill": candidate,
                "match_type": "explicit-skill",
                "router_source": "explicit",
                "reason": "用户显式点名一个已注册 skill；由目标 skill 执行边界自检",
            }
        return {
            "decision": "chat",
            "skill": fallback,
            "mode": "clarify",
            "match_type": "explicit-skill-ambiguous",
            "router_source": "explicit",
            "reason": "显式 skill 不唯一",
        }

    normalized = normalize_phrase(text)
    route_id = config["_aliases"].get(normalized)
    if route_id is not None:
        route = next(item for item in config["routes"] if item["id"] == route_id)
        candidate = route["target"]["skill"]
        mismatch = _scope_mismatch_reason(
            candidate,
            config,
            project_id=project_id,
            available_skills=available_skills,
        )
        if mismatch:
            return _scope_fallback(
                fallback=fallback,
                candidate_skill=candidate,
                match_type="exact-phrase-out-of-scope",
                reason=mismatch,
                route_id=route_id,
            )
        result = {
            "decision": "direct",
            "match_type": "exact-phrase",
            "router_source": "exact",
            "route_id": route_id,
            "reason": "完整输入命中全局唯一短语",
        }
        result.update(route["target"])
        return result

    return {
        "decision": "chat",
        "skill": fallback,
        "mode": "triage",
        "match_type": "fallback",
        "router_source": "deterministic",
        "reason": "未完整命中唯一短语；输入长度不参与直达判断",
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Workbench deterministic skill router")
    parser.add_argument("--config", default=str(DEFAULT_CONFIG))
    parser.add_argument("--index", default=str(DEFAULT_INDEX))
    parser.add_argument("--text", help="input text; omit to read stdin")
    parser.add_argument("--project", help="active project id; defaults to cwd inference")
    parser.add_argument(
        "--available-skill",
        action="append",
        dest="available_skills",
        help="restrict direct routes to the active Agent skill surface; repeatable",
    )
    parser.add_argument("--check", action="store_true", help="validate config only")
    args = parser.parse_args(argv)
    try:
        config = load_config(Path(args.config).resolve(), Path(args.index).resolve())
        if args.check:
            print(f"PASS: {len(config['_aliases'])} exact phrases, {len(config['routes'])} routes")
            return 0
        text = args.text if args.text is not None else sys.stdin.read()
        project_id = args.project or infer_project_from_path(Path.cwd())
        available = (
            set(args.available_skills)
            if args.available_skills
            else configured_available_skills(config, project_id=project_id)
        )
        print(
            json.dumps(
                route_text(
                    text,
                    config,
                    project_id=project_id,
                    available_skills=available,
                ),
                ensure_ascii=False,
                indent=2,
            )
        )
        return 0
    except RoutingConfigError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

