#!/usr/bin/env python3
"""Generate the Workbench skill source index."""
from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path
from typing import Any

from wb.workspace.paths import WB_ROOT
from wb.workspace import skill_access

ROOT = WB_ROOT
SKILLS_DIR = ROOT / "skills"
INDEX_PATH = SKILLS_DIR / "index.json"
SKILLS_CONFIG_PATH = ROOT / "configs" / "skills.yaml"
PROJECTION_CONFIG_PATH = SKILLS_CONFIG_PATH
FRONTMATTER_RE = re.compile(r"^---\n(.*?)\n---", re.S)
VALID_CATEGORIES = {"public", "baigong", "shuheng", "guanlan"}
CATEGORY_ALIASES = {"gaunlan": "guanlan"}
PROJECT_CATEGORIES = VALID_CATEGORIES - {"public"}
DEVELOP_TAG = "develop"
NON_SKILL_DIR_PREFIXES = (".", "_")


def load_projection_skill_sets(
    config_path: Path = PROJECTION_CONFIG_PATH,
) -> tuple[set[str], set[str]]:
    """从统一 skill 配置读取默认全局面和 develop 叠加面。"""
    try:
        if config_path == PROJECTION_CONFIG_PATH:
            global_skills, develop_skills, _, _ = skill_access.loadable_skill_sets()
            return global_skills, develop_skills
        else:
            from wb.workspace.config_layers import load_document
            payload = load_document(config_path)
    except FileNotFoundError as exc:
        raise ValueError(f"missing config: {config_path.relative_to(ROOT)}") from exc
    except (json.JSONDecodeError, ValueError) as exc:
        raise ValueError(f"invalid config: {config_path.relative_to(ROOT)}: {exc}") from exc
    raw_skills = payload.get("skills")
    if not isinstance(raw_skills, dict) or not raw_skills:
        raise ValueError(f"{config_path}: skills must be a non-empty object")
    result = {"global_loadable_skills": set(), "develop_loadable_skills": set()}
    for name, raw in raw_skills.items():
        if not isinstance(name, str) or not isinstance(raw, dict):
            raise ValueError(f"{config_path}: invalid skill item {name!r}")
        if raw.get("enabled") is not True:
            continue
        load = raw.get("load")
        if load == "global":
            result["global_loadable_skills"].add(name)
        elif load == "develop":
            result["develop_loadable_skills"].add(name)

    overlap = sorted(
        result["global_loadable_skills"] & result["develop_loadable_skills"]
    )
    if overlap:
        raise ValueError(
            "configs/skills.yaml global/develop skill lists overlap: "
            + ", ".join(overlap)
        )
    return (
        result["global_loadable_skills"],
        result["develop_loadable_skills"],
    )


def load_global_loadable_skills(
    config_path: Path = PROJECTION_CONFIG_PATH,
) -> set[str]:
    """兼容读取默认全局加载清单。"""
    return load_projection_skill_sets(config_path)[0]


def load_yaml(raw: str) -> dict[str, Any]:
    try:
        import yaml  # type: ignore

        value = yaml.safe_load(raw) or {}
        return value if isinstance(value, dict) else {}
    except Exception:
        parsed: dict[str, Any] = {}
        current_parent: str | None = None
        for line in raw.splitlines():
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            if not line.startswith((" ", "\t")) and line.rstrip().endswith(":"):
                current_parent = line.strip()[:-1]
                parsed.setdefault(current_parent, {})
                continue
            target = parsed
            stripped = line.strip()
            if current_parent and line.startswith((" ", "\t")):
                parent = parsed.setdefault(current_parent, {})
                target = parent if isinstance(parent, dict) else parsed
            if ":" not in stripped:
                continue
            key, value = stripped.split(":", 1)
            target[key.strip()] = value.strip().strip('"').strip("'")
        return parsed


def read_skill_frontmatter(skill_file: Path) -> dict[str, Any]:
    text = skill_file.read_text(encoding="utf-8")
    match = FRONTMATTER_RE.match(text)
    if not match:
        raise ValueError(f"missing frontmatter: {skill_file.relative_to(ROOT)}")
    metadata = load_yaml(match.group(1))
    if not metadata.get("name"):
        raise ValueError(f"missing frontmatter name: {skill_file.relative_to(ROOT)}")
    if not metadata.get("description"):
        raise ValueError(f"missing frontmatter description: {skill_file.relative_to(ROOT)}")
    return metadata


def read_openai_metadata(skill_dir: Path) -> dict[str, str]:
    openai_file = skill_dir / "agents" / "openai.yaml"
    if not openai_file.exists():
        return {}
    payload = load_yaml(openai_file.read_text(encoding="utf-8"))
    interface = payload.get("interface")
    if not isinstance(interface, dict):
        return {}
    result: dict[str, str] = {}
    for key in ("display_name", "short_description", "default_prompt"):
        value = interface.get(key)
        if isinstance(value, str) and value:
            result[key] = value
    return result


def read_short_description(metadata: dict[str, Any]) -> str | None:
    extra = metadata.get("metadata")
    if isinstance(extra, dict):
        for key in ("short-description", "short_description"):
            value = extra.get(key)
            if isinstance(value, str) and value:
                return value
    return None


def normalize_category(value: str) -> str:
    category = value.strip().lower()
    return CATEGORY_ALIASES.get(category, category)


def read_category(metadata: dict[str, Any]) -> str:
    extra = metadata.get("metadata")
    raw = extra.get("category") if isinstance(extra, dict) else None
    if not isinstance(raw, str) or not raw.strip():
        raise ValueError(f"missing metadata.category for skill {metadata.get('name')}")
    category = normalize_category(raw)
    if category != raw.strip().lower():
        raise ValueError(
            f"metadata.category for skill {metadata.get('name')} must use canonical value {category!r}"
        )
    if category not in VALID_CATEGORIES:
        allowed = ", ".join(sorted(VALID_CATEGORIES))
        raise ValueError(f"invalid metadata.category {raw!r} for skill {metadata.get('name')}; allowed: {allowed}")
    return category


def read_targets(metadata: dict[str, Any]) -> list[str]:
    """Read optional external-tool targets from SKILL.md frontmatter.

    pyyaml 缺失时简易 frontmatter 解析器会把 list 读为字符串，
    因此接受 list 与 "[a, b]" / "a, b" / "a" 形态。
    """
    extra = metadata.get("metadata")
    raw = extra.get("targets") if isinstance(extra, dict) else None
    if raw is None:
        return []
    if isinstance(raw, str):
        items = raw.strip().strip("[]").split(",")
    elif isinstance(raw, (list, tuple)):
        items = [str(item) for item in raw]
    else:
        return []
    seen: list[str] = []
    for item in items:
        value = str(item).strip().strip("\"'")
        if value and value not in seen:
            seen.append(value)
    return seen


def read_tags(metadata: dict[str, Any]) -> list[str]:
    extra = metadata.get("metadata")
    raw = extra.get("tags") if isinstance(extra, dict) else None
    if raw is None:
        return []
    if isinstance(raw, str):
        items = raw.strip().strip("[]").split(",")
    elif isinstance(raw, (list, tuple)):
        items = [str(item) for item in raw]
    else:
        return []
    seen: list[str] = []
    for item in items:
        value = str(item).strip().strip("\"'").lower()
        if value and value not in seen:
            seen.append(value)
    return seen


def iter_skill_dirs() -> list[tuple[Path, str | None]]:
    """Return skill source dirs and their path-owned project, if any."""
    result: list[tuple[Path, str | None]] = []
    if not SKILLS_DIR.exists():
        return result
    for entry in sorted(p for p in SKILLS_DIR.iterdir() if p.is_dir() and not p.name.startswith(NON_SKILL_DIR_PREFIXES)):
        skill_file = entry / "SKILL.md"
        if skill_file.exists():
            result.append((entry, None))
            continue
        if entry.name in PROJECT_CATEGORIES:
            for skill_dir in sorted(p for p in entry.iterdir() if p.is_dir() and not p.name.startswith(".")):
                nested_skill_file = skill_dir / "SKILL.md"
                if nested_skill_file.exists():
                    result.append((skill_dir, entry.name))
            continue
        raise ValueError(f"missing SKILL.md: {entry.relative_to(ROOT)}")
    return result


def build_index() -> dict[str, Any]:
    configured = skill_access.configured_skills()
    (
        global_loadable_skills,
        develop_loadable_skills,
        _,
        internal_skills,
    ) = skill_access.loadable_skill_sets()
    skills: list[dict[str, Any]] = []
    if not SKILLS_DIR.exists():
        return {
            "schema_version": 1,
            "description": "Workbench skill source index. Generated by python3 -m wb.agent.skill_index.",
            "global_loadable_skills": sorted(global_loadable_skills),
            "develop_loadable_skills": sorted(develop_loadable_skills),
            "internal_skills": sorted(internal_skills),
            "develop_tag": DEVELOP_TAG,
            "count": 0,
            "skills": [],
        }

    for skill_dir, project in iter_skill_dirs():
        skill_file = skill_dir / "SKILL.md"
        metadata = read_skill_frontmatter(skill_file)
        name = str(metadata["name"])
        if name != skill_dir.name:
            raise ValueError(f"frontmatter name {name!r} does not match directory {skill_dir.relative_to(ROOT)}")
        try:
            skill_config = configured[name]
        except KeyError as exc:
            raise ValueError(f"skill source missing from configs/skills.yaml: {name}") from exc
        load_mode = str(skill_config["load"])
        enabled = bool(skill_config["enabled"])
        category = read_category(metadata)
        entry: dict[str, Any] = {
            "name": name,
            "path": str(skill_file.relative_to(ROOT)),
            "description": str(metadata["description"]),
            "category": category,
            "enabled": enabled,
            "load": load_mode,
        }
        if project:
            if load_mode != "project":
                raise ValueError(
                    f"project skill {name} must use configs/skills.yaml load=project"
                )
            configured_projects = set(skill_config.get("projects") or [])
            if project not in configured_projects:
                raise ValueError(
                    f"project skill {name} must include project {project!r} in configs/skills.yaml"
                )
            entry["project"] = project
        elif load_mode == "project":
            raise ValueError(
                f"root skill {name} cannot use configs/skills.yaml load=project"
            )
        short_description = read_short_description(metadata)
        if short_description:
            entry["short_description"] = short_description
        entry.update(read_openai_metadata(skill_dir))
        targets = read_targets(metadata)
        if targets:
            entry["targets"] = targets
        tags = read_tags(metadata)
        if load_mode == "global":
            if category != "public":
                raise ValueError(f"global loadable skill {name} must use metadata.category public")
            if DEVELOP_TAG in tags:
                raise ValueError(f"global loadable skill {name} must not use metadata.tags: [develop]")
        elif load_mode == "develop":
            if category != "public":
                raise ValueError(f"develop loadable skill {name} must use metadata.category public")
