                )
            if DEVELOP_TAG not in tags:
                raise ValueError(f"project skill {name} must use metadata.tags: [develop]")
        if tags:
            entry["tags"] = tags
        skills.append(entry)

    seen: set[str] = set()
    for entry in skills:
        name = entry["name"]
        if name in seen:
            raise ValueError(f"duplicate skill name: {name}")
        seen.add(name)

    missing_global = sorted(global_loadable_skills - seen)
    if missing_global:
        raise ValueError(
            "configs/skills.yaml references missing global skills: "
            + ", ".join(missing_global)
        )
    missing_develop = sorted(develop_loadable_skills - seen)
    if missing_develop:
        raise ValueError(
            "configs/skills.yaml references missing develop skills: "
            + ", ".join(missing_develop)
        )
    missing_configured = sorted(set(configured) - seen)
    if missing_configured:
        raise ValueError(
            "configs/skills.yaml references missing skill sources: "
            + ", ".join(missing_configured)
        )

    return {
        "schema_version": 1,
        "description": "Workbench skill source index. Generated by python3 -m wb.agent.skill_index.",
        "global_loadable_skills": sorted(global_loadable_skills),
        "develop_loadable_skills": sorted(develop_loadable_skills),
        "internal_skills": sorted(internal_skills),
        "develop_tag": DEVELOP_TAG,
        "count": len(skills),
        "skills": sorted(skills, key=lambda item: item["name"]),
    }


def render_index(payload: dict[str, Any]) -> str:
    return json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=False) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate skills/index.json from Workbench skill source dirs")
    parser.add_argument("--check", action="store_true", help="fail if skills/index.json is missing or stale")
    args = parser.parse_args()

    try:
        payload = build_index()
        rendered = render_index(payload)
    except Exception as exc:
        print(f"FAIL: {exc}", file=sys.stderr)
        return 1

    if args.check:
        if not INDEX_PATH.exists():
            print(f"FAIL: missing {INDEX_PATH.relative_to(ROOT)}", file=sys.stderr)
            return 1
        current = INDEX_PATH.read_text(encoding="utf-8")
        if current != rendered:
            print(f"FAIL: stale {INDEX_PATH.relative_to(ROOT)}; run python3 -m wb.agent.skill_index", file=sys.stderr)
            return 1
