"""Resolve Workbench skill stages to public sn-cli profile execution settings."""

from __future__ import annotations

import argparse
from dataclasses import dataclass
import json
import os
from pathlib import Path
import re
from typing import Mapping, Sequence

from wb.workspace.config_layers import load_document
from wb.workspace.config_store import load_config as load_yaml_config
from wb.workspace.paths import WB_ROOT, display_path


DEFAULT_CONFIG = WB_ROOT / "configs" / "skills-execution.yaml"
DEFAULT_RUNTIME_CONFIG = WB_ROOT / "apps" / "agent" / "conf" / "skill-runtime.yaml"
DEFAULT_SCHEMA = WB_ROOT / "apps" / "agent" / "conf" / "schemas" / "skill-execution.schema.json"
PROFILE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
SKILL_RE = re.compile(r"^[a-z0-9][a-z0-9-]*$")
LOCAL_STAGE_RE = re.compile(r"^[a-z0-9][a-z0-9_]*$")
STAGE_RE = re.compile(r"^[a-z0-9][a-z0-9-]*\.[a-z0-9][a-z0-9_]*$")
HUMAN_SETTING_KEYS = frozenset({"profile"})
RUNTIME_SETTING_KEYS = frozenset({"fallback_profile", "live_progress"})
_UNSET = object()


class SkillExecutionError(ValueError):
    """Raised when the shared skill execution policy is invalid."""


@dataclass(frozen=True)
class ExecutionSettings:
    stage: str | None
    profile: str
    fallback_profile: str | None
    live_progress: bool
    config_path: Path

    def as_dict(self) -> dict[str, object]:
        return {
            "schema_version": 2,
            "stage": self.stage,
            "profile": self.profile,
            "fallback_profile": self.fallback_profile,
            "live_progress": self.live_progress,
            "config_path": display_path(self.config_path),
        }


@dataclass(frozen=True)
class ExecutionPolicy:
    config_path: Path
    defaults: Mapping[str, object]
    stages: Mapping[str, Mapping[str, object]]

    def resolve(
        self,
        stage: str | None,
        *,
        profile: str | None = None,
        fallback_profile: str | None | object = _UNSET,
        live_progress: bool | None = None,
    ) -> ExecutionSettings:
        normalized_stage = _validated_stage(stage) if stage else None
        merged = dict(self.defaults)
        if normalized_stage is not None:
            try:
                merged.update(self.stages[normalized_stage])
            except KeyError as exc:
                raise SkillExecutionError(f"未登记的 skill execution stage: {normalized_stage}") from exc

        resolved_profile = validated_profile(
            profile if profile is not None else merged.get("profile"),
            "profile",
        )
        fallback_value = (
            merged.get("fallback_profile")
            if fallback_profile is _UNSET
            else fallback_profile
        )
        resolved_fallback = _validated_optional_profile(
            fallback_value,
            "fallback_profile",
        )
        resolved_live_progress = (
            _validated_bool(merged.get("live_progress"), "live_progress")
            if live_progress is None
            else live_progress
        )
        return ExecutionSettings(
            stage=normalized_stage,
            profile=resolved_profile,
            fallback_profile=resolved_fallback,
            live_progress=resolved_live_progress,
            config_path=self.config_path,
        )


def validated_profile(value: object, field: str = "profile") -> str:
    profile = str(value or "").strip()
    if not profile or not PROFILE_RE.fullmatch(profile):
        raise SkillExecutionError(f"{field} 必须是合法的 sn-cli profile id")
    return profile


def _validated_optional_profile(value: object, field: str) -> str | None:
    if value is None:
        return None
    return validated_profile(value, field)


def _validated_stage(value: object) -> str:
    stage = str(value or "").strip()
    if not stage or not STAGE_RE.fullmatch(stage):
        raise SkillExecutionError(
            "stage 必须是 <skill>.<stage_name>，且 stage_name 只能包含小写字母、数字和下划线"
        )
    return stage


def _validated_local_stage(value: object) -> str:
    stage = str(value or "").strip()
    if not stage or not LOCAL_STAGE_RE.fullmatch(stage):
        raise SkillExecutionError(
            "local stage 必须以小写字母或数字开头，且只能包含小写字母、数字和下划线"
        )
    return stage


def _validated_skill(value: object) -> str:
    skill = str(value or "").strip()
    if not skill or not SKILL_RE.fullmatch(skill):
        raise SkillExecutionError("skill 必须是小写字母、数字或连字符组成的稳定标识")
    return skill


def _validated_bool(value: object, field: str) -> bool:
    if not isinstance(value, bool):
        raise SkillExecutionError(f"{field} 必须是 boolean")
    return value


def _validated_settings(
    value: object,
    *,
    field: str,
    allowed_keys: frozenset[str],
    required_keys: frozenset[str],
) -> dict[str, object]:
    if not isinstance(value, dict):
        raise SkillExecutionError(f"{field} 必须是 JSON object")
    unknown = sorted(set(value) - allowed_keys)
    if unknown:
        raise SkillExecutionError(f"{field} 包含未知字段: {', '.join(unknown)}")
    missing = sorted(required_keys - set(value))
    if missing:
        raise SkillExecutionError(f"{field} 缺少字段: {', '.join(missing)}")
    result = dict(value)
    if "profile" in result:
        result["profile"] = validated_profile(result["profile"], f"{field}.profile")
    if "fallback_profile" in result:
        result["fallback_profile"] = _validated_optional_profile(
            result["fallback_profile"],
            f"{field}.fallback_profile",
        )
    if "live_progress" in result:
        result["live_progress"] = _validated_bool(
            result["live_progress"],
            f"{field}.live_progress",
        )
    return result


def _human_stages(payload: object) -> dict[str, Mapping[str, object]]:
    if not isinstance(payload, dict):
        raise SkillExecutionError("skill execution 配置根节点必须是 YAML object")
    unknown = sorted(set(payload) - {"skills"})
    if unknown:
        raise SkillExecutionError(f"skill execution 配置包含未知字段: {', '.join(unknown)}")
    raw_skills = payload.get("skills")
    if not isinstance(raw_skills, dict) or not raw_skills:
        raise SkillExecutionError("skills 必须是非空 YAML object")
    stages: dict[str, Mapping[str, object]] = {}
    for raw_skill, raw_stages in raw_skills.items():
        skill = _validated_skill(raw_skill)
        if not isinstance(raw_stages, dict) or not raw_stages:
            raise SkillExecutionError(f"skills.{skill} 必须是非空 JSON object")
        for raw_stage, settings in raw_stages.items():
            local_stage = _validated_local_stage(raw_stage)
            canonical_stage = f"{skill}.{local_stage}"
            stages[canonical_stage] = _validated_settings(
                settings,
                field=f"skills.{skill}.{local_stage}",
                allowed_keys=HUMAN_SETTING_KEYS,
                required_keys=HUMAN_SETTING_KEYS,
            )
    return stages


def validate_stage_comments(path: Path, stages: set[str]) -> None:
    """校验共享人读配置中每个 Stage 的相邻说明和触发场景注释。"""

    current_skill: str | None = None
    documented: set[str] = set()
    lines = path.read_text(encoding="utf-8").splitlines()
    for index, line in enumerate(lines):
        skill_match = re.fullmatch(r"  ([a-z0-9][a-z0-9-]*):", line)
        if skill_match:
            current_skill = skill_match.group(1)
            continue
        stage_match = re.fullmatch(r"    ([a-z0-9][a-z0-9_]*):", line)
        if not stage_match or current_skill is None:
            continue
        stage = f"{current_skill}.{stage_match.group(1)}"
        if stage not in stages:
            continue
        previous = [
            item.strip()
            for item in lines[max(0, index - 4):index]
            if item.strip()
        ]
        if (
            len(previous) < 2
            or not previous[-2].startswith("# 说明：")
            or not previous[-1].startswith("# 触发场景：")
        ):
            raise SkillExecutionError(
                f"{stage} 必须紧邻 # 说明： 与 # 触发场景： 注释"
            )
        documented.add(stage)
    missing = sorted(stages - documented)
    if missing:
        raise SkillExecutionError(
            f"Stage 缺少说明或触发场景注释: {', '.join(missing)}"
        )


def resolve_config_path(
    path: str | Path | None = None,
    *,
    env: Mapping[str, str] | None = None,
) -> Path:
    values = os.environ if env is None else env
    raw = path or values.get("WB_SKILL_EXECUTION_CONFIG") or DEFAULT_CONFIG
    return Path(raw).expanduser().resolve()


def resolve_runtime_config_path(
    path: str | Path | None = None,
    *,
    env: Mapping[str, str] | None = None,
) -> Path:
    values = os.environ if env is None else env
    raw = path or values.get("WB_SKILL_RUNTIME_CONFIG") or DEFAULT_RUNTIME_CONFIG
    return Path(raw).expanduser().resolve()


def load_policy(
    path: str | Path | None = None,
    *,
    runtime_path: str | Path | None = None,
    env: Mapping[str, str] | None = None,
) -> ExecutionPolicy:
    values = os.environ if env is None else env
    strict_stage_alignment = (
        path is None and not values.get("WB_SKILL_EXECUTION_CONFIG")
    )
    config_path = resolve_config_path(path, env=env)
    resolved_runtime_path = resolve_runtime_config_path(runtime_path, env=env)
    shared_payload: object | None = None
    try:
        if config_path == DEFAULT_CONFIG:
            shared_payload = load_yaml_config(
                "skills-execution",
                include_local=False,
            ).data
            payload = load_yaml_config("skills-execution", include_local=True).data
        else:
            payload = load_document(config_path)
    except FileNotFoundError as exc:
        raise SkillExecutionError(f"skill execution 配置不存在: {config_path}") from exc
    except ValueError as exc:
        raise SkillExecutionError(f"skill execution 配置无法解析: {config_path}: {exc}") from exc
    stages = _human_stages(payload)
    if shared_payload is not None:
        shared_stages = _human_stages(shared_payload)
        local_only = sorted(set(stages) - set(shared_stages))
        if local_only:
            raise SkillExecutionError(
                "configs/local/skills-execution.yaml 只能覆盖已登记 Stage，"
                f"不能新增: {', '.join(local_only)}"
            )

    try:
        runtime_document = load_document(resolved_runtime_path)
    except FileNotFoundError as exc:
        raise SkillExecutionError(
