            f"skill runtime 配置无法解析: {resolved_runtime_path}: {exc}"
        ) from exc
    runtime = runtime_document.get("model_execution")
    if not isinstance(runtime, dict):
        raise SkillExecutionError("skill runtime.model_execution 必须是 YAML object")
    unknown_runtime = sorted(set(runtime) - {"defaults", "stages"})
    if unknown_runtime:
        raise SkillExecutionError(
            "skill runtime.model_execution 包含未知字段: "
            + ", ".join(unknown_runtime)
        )
    defaults = _validated_settings(
        runtime.get("defaults"),
        field="model_execution.defaults",
        allowed_keys=RUNTIME_SETTING_KEYS,
        required_keys=RUNTIME_SETTING_KEYS,
    )
    raw_runtime_stages = runtime.get("stages", {})
    if not isinstance(raw_runtime_stages, dict):
        raise SkillExecutionError("model_execution.stages 必须是 YAML object")
    for raw_stage, settings in raw_runtime_stages.items():
