            ),
        }
    return ExecutionPolicy(
        config_path=config_path,
        defaults=defaults,
        stages=stages,
    )


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Validate and resolve Workbench skill execution policy")
    parser.add_argument("--config", help="skill execution config path")
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("validate", help="validate the complete policy")
    list_parser = sub.add_parser("list", help="list configured stages")
    list_parser.add_argument("--json", action="store_true")
    resolve_parser = sub.add_parser("resolve", help="resolve one stage")
    resolve_parser.add_argument("--stage", required=True)
    resolve_parser.add_argument("--json", action="store_true")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        policy = load_policy(args.config)
        if args.command == "validate":
            schema = json.loads(DEFAULT_SCHEMA.read_text(encoding="utf-8"))
            if not isinstance(schema, dict) or schema.get("title") != "Workbench skill execution policy":
                raise SkillExecutionError(f"skill execution schema 无效: {DEFAULT_SCHEMA}")
            if policy.config_path == DEFAULT_CONFIG:
                validate_stage_comments(DEFAULT_CONFIG, set(policy.stages))
            print(
                json.dumps(
                    {
                        "ok": True,
                        "config": display_path(policy.config_path),
                        "schema": display_path(DEFAULT_SCHEMA),
                        "stage_count": len(policy.stages),
                    },
                    ensure_ascii=False,
                    indent=2,
                )
            )
            return 0
        if args.command == "list":
            data = {
                "config": display_path(policy.config_path),
                "stages": sorted(policy.stages),
            }
            if args.json:
                print(json.dumps(data, ensure_ascii=False, indent=2))
            else:
                print("\n".join(data["stages"]))
            return 0
        resolved = policy.resolve(args.stage)
        if args.json:
            print(json.dumps(resolved.as_dict(), ensure_ascii=False, indent=2))
        else:
            print(
                f"{resolved.stage}: profile={resolved.profile} "
                f"fallback={resolved.fallback_profile or 'disabled'} "
                f"live_progress={str(resolved.live_progress).lower()}"
            )
        return 0
    except (OSError, SkillExecutionError, json.JSONDecodeError) as exc:
        print(f"ERROR: {exc}", file=os.sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

