"""Shared Workbench route-envelope protocol helpers."""

from __future__ import annotations

import json
from typing import Any


ROUTED_CONTENT_PREFIX = "[[WORKBENCH_ROUTE_V1]]\n"
ROUTED_CONTENT_SEPARATOR = "\n[[USER_INPUT]]\n"


def decode_routed_content(content: str) -> tuple[str, dict[str, Any] | None]:
    """Return visible user text and its route payload when an envelope is present."""
    if not content.startswith(ROUTED_CONTENT_PREFIX):
        return content, None
    header, separator, original = content.partition(ROUTED_CONTENT_SEPARATOR)
    if not separator:
        return content, None
    try:
        routing = json.loads(header.removeprefix(ROUTED_CONTENT_PREFIX))
    except json.JSONDecodeError:
        return content, None
    if not isinstance(routing, dict):
        return content, None
    return original, routing

