def _optional_route_text(value: object) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _route_target(value: object, *, fallback: dict[str, Any] | None = None) -> dict[str, Any]:
    source = value if isinstance(value, dict) else fallback or {}
    return {
        "skill": _optional_route_text(source.get("skill")),
        "mode": _optional_route_text(source.get("mode")),
        "workflow": _optional_route_text(source.get("workflow")),
    }


def _route_handoff(value: object) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    skill = _optional_route_text(value.get("skill"))
    if not skill:
        raise FinalizeError("routing pending_handoff.skill is required")
    return {
        "skill": skill,
        "mode": _optional_route_text(value.get("mode")),
        "workflow": _optional_route_text(value.get("workflow")),
        "gate": _optional_route_text(value.get("gate")),
        "reason": _optional_route_text(value.get("reason")),
    }


def _normalize_routing_entries(values: list[dict[str, Any]]) -> list[dict[str, Any]]:
    normalized: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw in values:
        marker = json.dumps(raw, ensure_ascii=False, sort_keys=True)
        if marker in seen:
            continue
        seen.add(marker)
        decision = str(raw.get("decision") or "").strip()
        if decision not in {"direct", "chat"}:
            raise FinalizeError(f"routing decision is invalid: {decision or '<empty>'}")
        match_type = str(raw.get("match_type") or "").strip()
        if not match_type:
            raise FinalizeError("routing match_type is required")
        router_source = str(raw.get("router_source") or "").strip()
        if not router_source:
            if match_type.startswith("explicit-"):
                router_source = "explicit"
            elif match_type.startswith("exact-"):
                router_source = "exact"
            else:
                router_source = "deterministic"
        scores: dict[str, float | None] = {}
        for key in ("confidence", "margin"):
            value = raw.get(key)
            if value is None:
                scores[key] = None
                continue
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise FinalizeError(f"routing {key} must be numeric")
            score = float(value)
            if not 0 <= score <= 1:
                raise FinalizeError(f"routing {key} must be within 0..1")
            scores[key] = round(score, 6)
        target = _route_target(raw.get("target"), fallback=raw)
        if not target["skill"]:
            raise FinalizeError("routing target skill is required")
        active_owner = (
            _route_target(raw.get("active_owner"))
            if isinstance(raw.get("active_owner"), dict)
