#!/usr/bin/env python3
"""Dispatch one prompt through a configured sn-cli profile."""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import re
import shlex
import subprocess
import sys
import threading
import time


SKILL_DIR = Path(__file__).resolve().parent.parent
WB_ROOT = SKILL_DIR.parent.parent
if str(WB_ROOT) not in sys.path:
    sys.path.insert(0, str(WB_ROOT))

from wb.agent import skill_execution  # noqa: E402


DEFAULT_CONFIG = skill_execution.DEFAULT_CONFIG
LIVE_PROGRESS_INTERVAL_SECONDS = 10.0
MISSING_ENV_PATTERNS = (
    re.compile(r"环境变量未设置:\s*([A-Z_][A-Z0-9_]*)"),
    re.compile(r"environment variable\s+([A-Z_][A-Z0-9_]*)\s+is not set", re.IGNORECASE),
)
PROVIDER_HTTP_PATTERN = re.compile(r"provider API returned HTTP\s+(\d{3})", re.IGNORECASE)


class DispatchError(RuntimeError):
    """Raised when dispatch configuration or execution is invalid."""


def validated_profile(value: object, field: str) -> str:
    try:
        return skill_execution.validated_profile(value, field)
    except skill_execution.SkillExecutionError as exc:
        raise DispatchError(str(exc)) from exc


def load_config(path: Path | None = None) -> skill_execution.ExecutionPolicy:
    try:
        return skill_execution.load_policy(path)
    except skill_execution.SkillExecutionError as exc:
        raise DispatchError(str(exc)) from exc


def build_prompt(prompt_file: Path | None, task_parts: list[str], stdin_text: str) -> str:
    sections: list[str] = []
    if prompt_file is not None:
        try:
            sections.append(prompt_file.read_text(encoding="utf-8").strip())
        except FileNotFoundError as exc:
            raise DispatchError(f"prompt 文件不存在: {prompt_file}") from exc
    task = " ".join(part.strip() for part in task_parts if part.strip()).strip()
    if task:
        sections.append(f"## 用户补充输入\n\n{task}")
    if stdin_text.strip():
        sections.append(stdin_text.strip())
    prompt = "\n\n".join(section for section in sections if section).strip()
    if not prompt:
        raise DispatchError("prompt 不能为空")
    return prompt


def emit_live_progress(
    profile: str,
    state: str,
    started_at: float,
    *,
    exit_code: int | None = None,
    reason: str | None = None,
) -> None:
    elapsed_seconds = max(0, int(time.monotonic() - started_at))
    suffix = f" exit={exit_code}" if exit_code is not None else ""
    if reason is not None:
        suffix += f" reason={reason}"
    print(
        f"[wb-model] profile={profile} {state} elapsed={elapsed_seconds}s{suffix}",
        file=sys.stderr,
        flush=True,
    )
    payload: dict[str, object] = {
        "schema_version": 1,
        "profile": profile,
        "state": state,
        "elapsed_seconds": elapsed_seconds,
    }
    if exit_code is not None:
        payload["exit_code"] = exit_code
    if reason is not None:
        payload["reason"] = reason
    print(
        "WB_MODEL_PROGRESS "
        + json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
        file=sys.stderr,
        flush=True,
    )


def live_progress_heartbeat(
    profile: str,
    started_at: float,
    finished: threading.Event,
) -> None:
    while not finished.wait(LIVE_PROGRESS_INTERVAL_SECONDS):
        emit_live_progress(profile, "running", started_at)


def classify_profile_failure(stderr: str) -> dict[str, str]:
    for pattern in MISSING_ENV_PATTERNS:
        match = pattern.search(stderr)
        if match:
            return {"reason": "missing-env", "variable": match.group(1)}
    match = PROVIDER_HTTP_PATTERN.search(stderr)
    if match:
        return {"reason": "provider-http", "status": match.group(1)}
    lowered = stderr.lower()
    if "context deadline exceeded" in lowered or "timed out" in lowered:
        return {"reason": "provider-timeout"}
    if (
        "response contains no text output" in lowered
        or "decode provider api response" in lowered
    ):
        return {"reason": "invalid-provider-response"}
    return {"reason": "profile-exit"}


def render_failure_details(details: dict[str, str]) -> str:
    values = [f"reason={details['reason']}"]
    for field in ("variable", "status"):
        if field in details:
            values.append(f"{field}={details[field]}")
    return ", ".join(values)


def invoke_profile(
    sn_cli: str,
    profile: str,
    prompt: str,
    *,
    live_progress: bool = False,
) -> str:
    started_at = time.monotonic()
    finished = threading.Event()
    heartbeat: threading.Thread | None = None
    if live_progress:
        emit_live_progress(profile, "started", started_at)
        heartbeat = threading.Thread(
            target=live_progress_heartbeat,
            args=(profile, started_at, finished),
            daemon=True,
        )
        heartbeat.start()
    try:
        result = subprocess.run(
            [sn_cli, "profile", "exec", profile],
            input=prompt,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
        )
    except OSError as exc:
        if live_progress:
            emit_live_progress(profile, "failed", started_at)
        raise DispatchError(f"无法执行 profile {profile}: {exc.__class__.__name__}") from exc
    finally:
        finished.set()
        if heartbeat is not None:
            heartbeat.join()
    if result.returncode != 0:
        details = classify_profile_failure(result.stderr)
        if live_progress:
            emit_live_progress(
                profile,
                "failed",
                started_at,
                exit_code=result.returncode,
                reason=details["reason"],
            )
        raise DispatchError(
            f"profile {profile} 执行失败(exit={result.returncode}, "
            f"{render_failure_details(details)})"
        )
    output = result.stdout.strip()
    if not output:
        if live_progress:
            emit_live_progress(profile, "failed", started_at, exit_code=result.returncode)
        raise DispatchError(f"profile {profile} 返回空输出")
    if live_progress:
        emit_live_progress(profile, "completed", started_at, exit_code=result.returncode)
    return output


def resolved_provider_command(sn_cli: str, profile: str) -> str | None:
    """Resolve a CLI profile without starting the provider.

    API/native profiles and older sn-cli builds may not expose a provider argv. In
    that case callers still get the public sn-cli entry command.
    """
    try:
        result = subprocess.run(
            [sn_cli, "profile", "command", profile, "--mode", "exec", "--json"],
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
        )
    except OSError:
        return None
    if result.returncode != 0:
        return None
    try:
        payload = json.loads(result.stdout)
    except json.JSONDecodeError:
        return None
    if not isinstance(payload, dict) or payload.get("profile") != profile:
        return None
    command = payload.get("command")
    if isinstance(command, str) and command.strip():
        return command.strip()
    argv = payload.get("argv")
    if isinstance(argv, list) and argv and all(isinstance(item, str) for item in argv):
        return shlex.join(argv)
    return None


def print_resolved_commands(
    *,
    sn_cli: str,
    primary: str,
    fallback: str | None,
    fallback_enabled: bool,
) -> None:
    print(f"primary: {shlex.join([sn_cli, 'profile', 'exec', primary])}")
    primary_provider = resolved_provider_command(sn_cli, primary)
    print(f"primary-provider: {primary_provider or 'unavailable'}")
    if not fallback_enabled or fallback is None or fallback == primary:
        print("fallback: disabled")
    else:
        print(f"fallback: {shlex.join([sn_cli, 'profile', 'exec', fallback])}")
        fallback_provider = resolved_provider_command(sn_cli, fallback)
        print(f"fallback-provider: {fallback_provider or 'unavailable'}")
    print("prompt-delivery: stdin")


def dispatch(
    *,
    sn_cli: str,
