        session_id: str = "", deadline_seconds: int = 0, record_mode: str = "",
        retention: str = "", provider_overrides: dict[str, Any] | None = None,
        model: str = "", reasoning_effort: str = "", raw_cli_args: list[str] | None = None,
        force: bool = False, action: str = "run", queue_timeout_seconds: int = 0,
    ) -> list[str]:
        if action not in {"run", "submit"}:
            raise ValueError("task action must be run or submit")
        if provider_overrides:
            raise ValueError("provider_overrides 已退出公共 sn-cli 契约；请改用 profile 配置")
        if model:
            raise ValueError("model 必须由 sn-cli profile 配置")
        if reasoning_effort:
            raise ValueError("reasoning_effort 必须由 sn-cli profile 配置")
        args = [self.binary, "session", action]
        for option, value in (
            ("--run-id", run_id), ("--session-id", session_id), ("--project", project_id),
            ("--cwd", cwd), ("--record-mode", record_mode), ("--retention", retention),
        ):
            if value:
                args.extend([option, str(value)])
        if deadline_seconds > 0:
            args.extend(["--deadline-seconds", str(deadline_seconds)])
        if queue_timeout_seconds > 0:
            args.extend(["--queue-timeout-seconds", str(queue_timeout_seconds)])
        if force:
            args.append("--force")
        args.append(profile)
        if raw_cli_args:
            args.extend(raw_cli_args)
        return args

    def task_result(self, run_id: str) -> dict:
        return self._call(["run", "result", "--run-id", run_id])

    def list_runs(
        self, *, active: bool = False, state: str = "", run_type: str = "",
        project_id: str = "", profile: str = "", limit: int = 100,
    ) -> list[dict]:
        self.ensure_compatible()
        args = ["run", "list", "--limit", str(limit)]
        if active:
            args.append("--active")
        for option, value in (
            ("--state", state), ("--type", run_type), ("--project", project_id), ("--profile", profile),
        ):
            if value:
                args.extend([option, value])
        return list(self._call(args).get("runs") or [])

    def reconcile_runs(self, *, dry_run: bool = True) -> dict:
        self.ensure_compatible()
        args = ["run", "reconcile"]
        if dry_run:
            args.append("--dry-run")
        return self._call(args)

    def start_command(
        self, *, profile: str, argv: list[str], project_id: str, run_id: str,
        cwd: str, label: str, input_text: str | None, deadline_seconds: int,
        force: bool = False,
    ) -> dict:
        if not argv:
            raise ValueError("command argv is required")
        self.ensure_compatible()
        args = [
            "command", "start", "-c", profile, "--project", project_id,
            "--run-id", run_id, "--cwd", cwd, "--label", label,
            "--deadline-seconds", str(deadline_seconds),
        ]
        if force:
            args.append("--force")
        if input_text is None:
            return self._call([*args, "--", *argv])
        with tempfile.TemporaryDirectory(prefix="sn-cli-input-") as raw_dir:
            input_file = Path(raw_dir) / "input.txt"
            input_file.write_text(input_text, encoding="utf-8")
            return self._call([*args, "--input-file", str(input_file), "--", *argv])

    def command_status(self, run_id: str) -> dict:
        return self._call(["command", "status", "--run-id", run_id])

    def command_logs(self, run_id: str, *, tail: int = 200) -> dict:
        return self._call(["command", "logs", "--run-id", run_id, "--tail", str(tail)])

    def command_interrupt(self, run_id: str) -> dict:
        return self._call(["command", "interrupt", "--run-id", run_id], check=False)

    def command_stop(self, run_id: str) -> dict:
        return self._call(["command", "stop", "--run-id", run_id], check=False)

    def command_attach_argv(self, run_id: str) -> list[str]:
        return [self.binary, "command", "attach", "--run-id", run_id]

    def run_profile(
        self, *, profile: str, prompt: str, cwd: str | Path, timeout_seconds: int,
        provider_overrides: dict[str, Any] | None = None, env: dict[str, str] | None = None,
        raw_cli_args: list[str] | None = None,
    ) -> subprocess.CompletedProcess[str]:
        self.ensure_compatible()
        if provider_overrides:
            raise ValueError("provider_overrides 已退出公共 sn-cli 契约；请改用 profile 配置")
        command = [self.binary, "profile", "exec", profile]
        if raw_cli_args:
            command.extend(raw_cli_args)
        process_env = None if env is None else {**os.environ, **env}
        return subprocess.run(
            command, cwd=str(cwd), input=prompt, text=True, capture_output=True,
            timeout=timeout_seconds + 10 if timeout_seconds > 0 else None,
            env=process_env, check=False,
        )

    def list_sessions(self, project_id: str | None = None, limit: int = 200, tag: str | None = None) -> list[dict]:
        args = ["session", "list", "--limit", str(limit)]
        if project_id:
            args.extend(["--project", project_id])
        if tag:
            args.extend(["--tag", tag])
        return list(self._call(args).get("sessions") or [])

    def run_task(
        self, *, profile: str, project_id: str, cwd: str, prompt: str, timeout_seconds: int,
        run_id: str = "", provider_overrides: dict[str, Any] | None = None, force: bool = False,
    ) -> dict:
        self.ensure_compatible()
        run_id = run_id or f"task-{time.strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:6]}"
        command = self.task_run_command(
            profile=profile, run_id=run_id, project_id=project_id, cwd=cwd,
            deadline_seconds=timeout_seconds,
