#!/usr/bin/env python3
"""Shared skill execution policy tests."""

from __future__ import annotations

import json
from pathlib import Path
import tempfile
import unittest
from unittest import mock

from wb.agent import skill_execution


class SkillExecutionPolicyTest(unittest.TestCase):
    def _config(self, directory: str, payload: object) -> Path:
        path = Path(directory) / "skill-execution.json"
        path.write_text(json.dumps(payload), encoding="utf-8")
        return path

    def _runtime(self, directory: str, payload: object) -> Path:
        path = Path(directory) / "skill-runtime.json"
        path.write_text(
            json.dumps({"model_execution": payload}),
            encoding="utf-8",
        )
        return path

    def test_resolve_combines_human_profiles_and_machine_runtime(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = self._config(
                directory,
                {
                    "skills": {
                        "wb-repo": {
                            "inspect": {"profile": "cx-spark"},
                        },
                        "wb-git": {
                            "commit_plan": {"profile": "commit"},
                        },
                    },
                },
            )
            runtime = self._runtime(
                directory,
                {
                    "defaults": {
                        "fallback_profile": "cx",
                        "live_progress": False,
                    },
                    "stages": {
                        "wb-git.commit_plan": {
                            "fallback_profile": None,
                            "live_progress": True,
                        }
                    },
                },
            )
            policy = skill_execution.load_policy(path, runtime_path=runtime)

        inspect = policy.resolve("wb-repo.inspect")
        commit = policy.resolve("wb-git.commit_plan")
        self.assertEqual(inspect.profile, "cx-spark")
        self.assertEqual(inspect.fallback_profile, "cx")
        self.assertEqual(commit.profile, "commit")
        self.assertIsNone(commit.fallback_profile)
        self.assertTrue(commit.live_progress)

    def test_current_wb_repo_stage_set_has_six_execution_policies(self) -> None:
        policy = skill_execution.load_policy()
        repo_stages = {
            stage for stage in policy.stages if stage.startswith("wb-repo.")
        }

        self.assertEqual(
            repo_stages,
            {
                "wb-repo.inspect",
                "wb-repo.review",
                "wb-repo.diagnosis",
                "wb-repo.health_scan",
                "wb-repo.understand_evidence",
                "wb-repo.understand_report",
            },
        )
        expected_profiles = {
            "wb-repo.inspect": ("cx-spark", "cx-deep"),
            "wb-repo.review": ("cx-spark", "cx-deep"),
            "wb-repo.diagnosis": ("cx-deep", "cx-spark"),
            "wb-repo.health_scan": ("cx-spark", "cx-deep"),
            "wb-repo.understand_evidence": ("cx-spark", "cx-deep"),
            "wb-repo.understand_report": ("cx-deep", "cx-spark"),
        }
        for stage, (profile, fallback_profile) in expected_profiles.items():
            with self.subTest(stage=stage):
                resolved = policy.resolve(stage)
                self.assertEqual(resolved.profile, profile)
                self.assertEqual(resolved.fallback_profile, fallback_profile)

    def test_current_shared_stages_have_description_and_trigger_comments(self) -> None:
        policy = skill_execution.load_policy()

        skill_execution.validate_stage_comments(
            skill_execution.DEFAULT_CONFIG,
            set(policy.stages),
        )

    def test_stage_comment_validation_rejects_missing_trigger(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "skills-execution.yaml"
            path.write_text(
                "\n".join(
                    (
                        "skills:",
                        "  wb-repo:",
                        "    # 说明：测试说明。",
                        "    inspect:",
                        "      profile: cx",
                    )
                ),
                encoding="utf-8",
            )

            with self.assertRaisesRegex(
                skill_execution.SkillExecutionError,
                "必须紧邻",
            ):
                skill_execution.validate_stage_comments(
                    path,
                    {"wb-repo.inspect"},
                )

    def test_unknown_stage_fails_closed(self) -> None:
        policy = skill_execution.load_policy()
        with self.assertRaisesRegex(skill_execution.SkillExecutionError, "未登记"):
            policy.resolve("wb-repo.missing")

    def test_nested_or_hyphenated_local_stage_is_rejected(self) -> None:
        invalid_names = ("inspect.summary", "commit-message")
        for invalid_name in invalid_names:
            with self.subTest(stage=invalid_name), tempfile.TemporaryDirectory() as directory:
                path = self._config(
                    directory,
                    {
                        "skills": {
                            "wb-repo": {invalid_name: {"profile": "cx"}}
                        },
                    },
                )
                with self.assertRaisesRegex(
                    skill_execution.SkillExecutionError,
                    "local stage",
                ):
                    skill_execution.load_policy(path)

    def test_canonical_stage_has_exactly_one_separator(self) -> None:
        policy = skill_execution.load_policy()
        with self.assertRaisesRegex(
            skill_execution.SkillExecutionError,
            "stage 必须是",
        ):
            policy.resolve("wb-repo.inspect.summary")

    def test_config_path_can_be_overridden_by_one_environment_variable(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = self._config(
                directory,
                {
                    "skills": {
                        "wb-repo": {"health_scan": {"profile": "cc"}}
                    },
                },
            )
            policy = skill_execution.load_policy(
                env={"WB_SKILL_EXECUTION_CONFIG": str(path)}
            )

        self.assertEqual(policy.config_path, path.resolve())
        self.assertEqual(policy.resolve("wb-repo.health_scan").profile, "cc")

    def test_default_policy_applies_local_profile_overrides(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            config_root = Path(directory) / "configs"
            local_root = config_root / "local"
            local_root.mkdir(parents=True)
            shared_path = config_root / "skills-execution.yaml"
            local_path = local_root / "skills-execution.yaml"
            shared_path.write_text(
                json.dumps(
                    {
                        "skills": {
                            "wb-chat": {
                                "semantic_routing": {"profile": "cc"},
                                "routing_evaluation": {"profile": "cc"},
                            },
                        },
                    }
                ),
                encoding="utf-8",
            )
            local_path.write_text(
                json.dumps(
                    {
                        "skills": {
                            "wb-chat": {
                                "semantic_routing": {"profile": "cx-adv"},
                                "routing_evaluation": {"profile": "cx-adv"},
                            },
                        },
                    }
                ),
                encoding="utf-8",
            )
            runtime_path = self._runtime(
                directory,
                {
                    "defaults": {
                        "fallback_profile": "cx",
                        "live_progress": False,
                    },
                    "stages": {
                        "wb-chat.semantic_routing": {"fallback_profile": None},
                        "wb-chat.routing_evaluation": {"fallback_profile": None},
                    },
                },
            )
            with (
                mock.patch.object(
                    skill_execution,
                    "DEFAULT_CONFIG",
                    shared_path.resolve(),
                ),
                mock.patch(
                    "wb.workspace.config_store.CONFIG_ROOT",
                    config_root,
                ),
                mock.patch(
                    "wb.workspace.config_store.LOCAL_CONFIG_ROOT",
                    local_root,
                ),
                mock.patch.object(
                    skill_execution,
                    "DEFAULT_RUNTIME_CONFIG",
                    runtime_path.resolve(),
                ),
            ):
                policy = skill_execution.load_policy()

        semantic = policy.resolve("wb-chat.semantic_routing")
        evaluation = policy.resolve("wb-chat.routing_evaluation")
        self.assertEqual(semantic.profile, "cx-adv")
        self.assertEqual(evaluation.profile, "cx-adv")
        self.assertIsNone(semantic.fallback_profile)
        self.assertIsNone(evaluation.fallback_profile)

    def test_local_profile_override_cannot_register_new_stage(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            config_root = Path(directory) / "configs"
            local_root = config_root / "local"
            local_root.mkdir(parents=True)
            shared_path = config_root / "skills-execution.yaml"
            local_path = local_root / "skills-execution.yaml"
            shared_path.write_text(
                json.dumps(
                    {
                        "skills": {
                            "wb-chat": {
                                "semantic_routing": {"profile": "cc"},
                            },
                        },
                    }
                ),
                encoding="utf-8",
            )
            local_path.write_text(
                json.dumps(
                    {
                        "skills": {
                            "wb-chat": {
                                "unregistered": {"profile": "cx-adv"},
                            },
                        },
                    }
                ),
                encoding="utf-8",
            )
            runtime_path = self._runtime(
                directory,
                {
                    "defaults": {
                        "fallback_profile": "cx",
                        "live_progress": False,
                    },
                    "stages": {},
                },
            )
            with (
                mock.patch.object(
                    skill_execution,
                    "DEFAULT_CONFIG",
                    shared_path.resolve(),
                ),
                mock.patch(
                    "wb.workspace.config_store.CONFIG_ROOT",
                    config_root,
                ),
                mock.patch(
                    "wb.workspace.config_store.LOCAL_CONFIG_ROOT",
                    local_root,
                ),
                mock.patch.object(
                    skill_execution,
                    "DEFAULT_RUNTIME_CONFIG",
                    runtime_path.resolve(),
                ),
            ):
                with self.assertRaisesRegex(
                    skill_execution.SkillExecutionError,
                    "只能覆盖已登记 Stage",
                ):
                    skill_execution.load_policy()

    def test_unknown_fields_and_invalid_profiles_are_rejected(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = self._config(
                directory,
                {
                    "skills": {
                        "wb-repo": {
                            "health_scan": {
                                "profile": "cx spark",
                                "command": ["sn-cli", "cx"],
                            }
                        }
                    },
                },
            )
            with self.assertRaises(skill_execution.SkillExecutionError):
                skill_execution.load_policy(path)

    def test_legacy_flat_stages_are_rejected(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            path = self._config(
                directory,
                {
                    "stages": {"wb-repo.health_scan": {}},
                },
            )
            with self.assertRaisesRegex(skill_execution.SkillExecutionError, "未知字段"):
                skill_execution.load_policy(path)


if __name__ == "__main__":
    unittest.main()

