#!/usr/bin/env python3
"""Evaluate deterministic and wb-chat semantic routing against labeled utterances."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
import re
import sys
from typing import Any

from wb.agent.chat_router import DEFAULT_PROMPT as DEFAULT_SEMANTIC_PROMPT
from wb.agent.chat_router import route_locally
from wb.agent.skill_router import (
    DEFAULT_CONFIG,
    DEFAULT_INDEX,
    configured_available_skills,
    load_config,
    route_text,
)
from wb.workspace.paths import WB_ROOT


DEFAULT_CASES = WB_ROOT / "skills" / "wb-chat" / "references" / "routing-evaluation-cases.json"


class RoutingEvaluationError(ValueError):
    """Raised when an evaluation dataset or prediction file is invalid."""


def load_cases(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise RoutingEvaluationError(f"评测集不存在: {path}") from exc
    except json.JSONDecodeError as exc:
        raise RoutingEvaluationError(f"评测集不是合法 JSON: {path}: {exc}") from exc
    if not isinstance(payload, dict) or payload.get("schema_version") != 2:
        raise RoutingEvaluationError("评测集必须是 schema_version=2 的 JSON object")
    for key in (
        "minimum_top1_accuracy",
        "minimum_accepted_precision",
        "minimum_coverage",
        "minimum_route_contract_accuracy",
    ):
        minimum = payload.get(key)
        if (
            not isinstance(minimum, (int, float))
            or isinstance(minimum, bool)
            or not 0 < float(minimum) <= 1
        ):
            raise RoutingEvaluationError(f"{key} 必须在 (0, 1] 范围内")
    cases = payload.get("cases")
    if not isinstance(cases, list) or not cases:
        raise RoutingEvaluationError("cases 必须是非空 array")
    seen: set[str] = set()
    for case in cases:
        if not isinstance(case, dict):
            raise RoutingEvaluationError("case 必须是 JSON object")
        case_id = case.get("id")
        if not isinstance(case_id, str) or not case_id or case_id in seen:
            raise RoutingEvaluationError(f"case id 为空或重复: {case_id!r}")
        seen.add(case_id)
        if case.get("lane") not in {"deterministic", "semantic"}:
            raise RoutingEvaluationError(f"case {case_id} lane 必须是 deterministic 或 semantic")
        for key in ("input", "expected_skill"):
            if not isinstance(case.get(key), str) or not case[key].strip():
                raise RoutingEvaluationError(f"case {case_id} 缺少 {key}")
        expected_decision = case.get("expected_decision")
        if expected_decision not in {"route", "answer", "clarify"}:
            raise RoutingEvaluationError(
                f"case {case_id} expected_decision 必须是 route/answer/clarify"
            )
        if expected_decision == "route" and case["expected_skill"] == "wb-chat":
            raise RoutingEvaluationError(
                f"case {case_id} route 不得以 wb-chat 为 expected_skill"
            )
        if expected_decision in {"answer", "clarify"} and case["expected_skill"] != "wb-chat":
            raise RoutingEvaluationError(
                f"case {case_id} answer/clarify 必须以 wb-chat 为 expected_skill"
            )
    return payload


def load_predictions(path: Path | None) -> dict[str, dict[str, Any]]:
    if path is None:
        return {}
    try:
        candidate = path.read_text(encoding="utf-8").strip()
        fenced = re.fullmatch(
            r"```(?:json)?\s*(.*?)\s*```",
            candidate,
            flags=re.DOTALL | re.IGNORECASE,
        )
        if fenced:
            candidate = fenced.group(1).strip()
        payload = json.loads(candidate)
    except (FileNotFoundError, json.JSONDecodeError) as exc:
        raise RoutingEvaluationError(f"prediction 文件不可读: {path}: {exc}") from exc
    if not isinstance(payload, dict) or payload.get("schema_version") != 2:
        raise RoutingEvaluationError("prediction 必须是 schema_version=2 的 JSON object")
    items = payload.get("predictions")
    if not isinstance(items, list):
        raise RoutingEvaluationError("predictions 必须是 array")
    result: dict[str, dict[str, Any]] = {}
    for item in items:
        if not isinstance(item, dict) or not isinstance(item.get("id"), str):
            raise RoutingEvaluationError("prediction item 必须包含 string id")
        if item["id"] in result:
            raise RoutingEvaluationError(f"prediction id 重复: {item['id']}")
        if not isinstance(item.get("skill"), str) or not item["skill"]:
            raise RoutingEvaluationError(f"prediction {item['id']} 缺少 skill")
        if item.get("decision") not in {"route", "answer", "clarify"}:
            raise RoutingEvaluationError(
                f"prediction {item['id']} decision 必须是 route/answer/clarify"
            )
        score = item.get("score")
        if (
            not isinstance(score, (int, float))
            or isinstance(score, bool)
            or not 0 <= float(score) <= 1
        ):
            raise RoutingEvaluationError(
                f"prediction {item['id']} score 必须在 [0, 1] 范围内"
            )
        runner_skill = item.get("runner_up_skill")
        runner_score = item.get("runner_up_score")
        if (runner_skill is None) != (runner_score is None):
            raise RoutingEvaluationError(
                f"prediction {item['id']} runner-up skill/score 必须同时为 null 或同时存在"
            )
        if runner_skill is not None:
            if not isinstance(runner_skill, str) or not runner_skill:
                raise RoutingEvaluationError(
                    f"prediction {item['id']} runner_up_skill 必须是 string 或 null"
                )
            if runner_skill == item["skill"]:
                raise RoutingEvaluationError(
                    f"prediction {item['id']} runner_up_skill 不得等于 skill"
                )
            if (
                not isinstance(runner_score, (int, float))
                or isinstance(runner_score, bool)
                or not 0 <= float(runner_score) <= 1
            ):
                raise RoutingEvaluationError(
                    f"prediction {item['id']} runner_up_score 必须在 [0, 1] 范围内"
                )
        result[item["id"]] = item
    return result


def _local_prediction(
    case: dict[str, Any],
    routing_config: dict[str, Any],
) -> dict[str, Any] | None:
    project_id = case.get("project_id")
    result = route_locally(
        case["input"],
        routing_config,
        project_id=project_id,
        available_skills=configured_available_skills(
            routing_config,
            project_id=project_id,
            include_develop=True,
        ),
    )
    if result is None:
        return None
    runner = result.get("runner_up")
    runner = runner if isinstance(runner, dict) else {}
    return {
        "skill": result.get("skill"),
        "decision": (
            "route"
            if result.get("decision") == "direct"
            else "answer"
            if result.get("mode") == "answer"
            else "clarify"
        ),
        "score": float(result.get("confidence") or 0.0),
        "runner_up_skill": runner.get("skill"),
        "runner_up_score": runner.get("score"),
    }


def semantic_model_cases(
    dataset: dict[str, Any],
    routing_config: dict[str, Any],
) -> list[dict[str, Any]]:
    return [
        case
        for case in dataset["cases"]
        if case["lane"] == "semantic"
        and _local_prediction(case, routing_config) is None
    ]


def evaluate(
    dataset: dict[str, Any],
    routing_config: dict[str, Any],
    *,
    predictions: dict[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    predictions = predictions or {}
    local_predictions = {
        case["id"]: local
        for case in dataset["cases"]
        if case["lane"] == "semantic"
        if (local := _local_prediction(case, routing_config)) is not None
    }
    semantic_ids = {
        case["id"] for case in semantic_model_cases(dataset, routing_config)
    }
    unknown_ids = sorted(set(predictions) - semantic_ids)
    if unknown_ids:
        raise RoutingEvaluationError(
            "prediction 包含非 semantic case: " + ", ".join(unknown_ids)
        )
    invalid_skills = sorted(
        {
            str(skill)
            for item in predictions.values()
            for skill in (item.get("skill"), item.get("runner_up_skill"))
            if skill is not None
            and (
                skill not in routing_config["_known_skills"]
                or skill in routing_config["_internal_skills"]
            )
        }
    )
    if invalid_skills:
        raise RoutingEvaluationError(
            "prediction 包含未知或内部 skill: " + ", ".join(invalid_skills)
        )
    rows: list[dict[str, Any]] = []
    for case in dataset["cases"]:
        lane = case["lane"]
        if lane == "deterministic":
            routed = route_text(
                case["input"],
                routing_config,
                project_id=case.get("project_id"),
            )
            actual = {
                "skill": routed.get("skill"),
                "decision": (
                    "route" if routed.get("decision") == "direct" else "clarify"
                ),
                "score": 1.0 if routed.get("decision") == "direct" else 0.0,
                "runner_up_skill": None,
                "runner_up_score": None,
            }
            source = "skill_router"
        else:
            actual = local_predictions.get(case["id"])
            if actual is not None:
                source = "wb-chat-self"
            else:
                actual = predictions.get(case["id"])
                source = "wb-chat-prediction"
        measured = isinstance(actual, dict)
        actual_skill = str(actual.get("skill") or "") if measured else ""
        actual_decision = str(actual.get("decision") or "") if measured else ""
        score = float(actual.get("score") or 0.0) if measured else 0.0
        runner_score = (
            float(actual["runner_up_score"])
            if measured and actual.get("runner_up_score") is not None
            else 0.0
        )
        margin = score - runner_score
        matched = actual_skill == case["expected_skill"] if measured else None
        decision_matched = (
            actual_decision == case["expected_decision"] if measured else None
        )
        shape_valid = (
            (
                actual_decision == "route"
                and actual_skill != "wb-chat"
            )
            or (
                actual_decision in {"answer", "clarify"}
                and actual_skill == "wb-chat"
            )
        ) if measured else False
        accepted = bool(
            measured
            and actual_decision in {"route", "answer"}
            and score >= float(routing_config["_semantic_routing"]["model_accept_threshold"])
            and margin >= float(routing_config["_semantic_routing"]["minimum_margin"])
        )
        acceptance_contract_valid = (
            not measured
            or actual_decision == "clarify"
            or accepted
        )
        route_contract_matched = bool(
            measured and decision_matched and shape_valid and acceptance_contract_valid
        )
        rows.append(
            {
                "id": case["id"],
                "lane": lane,
                "source": source,
                "expected_skill": case["expected_skill"],
                "expected_decision": case["expected_decision"],
                "actual_skill": actual_skill or None,
                "actual_decision": actual_decision or None,
                "score": score if measured else None,
                "margin": margin if measured else None,
                "accepted": accepted if measured else None,
                "measured": measured,
                "matched": matched,
                "decision_matched": decision_matched,
                "route_contract_matched": (
                    route_contract_matched if measured else None
                ),
            }
        )

    measured_rows = [row for row in rows if row["measured"]]
    semantic_rows = [row for row in rows if row["lane"] == "semantic"]
    measured_semantic = [row for row in semantic_rows if row["measured"]]
    semantic_model_rows = [
        row for row in semantic_rows if row["source"] == "wb-chat-prediction"
    ]
    measured_semantic_model = [
        row for row in semantic_model_rows if row["measured"]
    ]
    deterministic_rows = [row for row in rows if row["lane"] == "deterministic"]
    correct = sum(1 for row in measured_rows if row["matched"])
    accepted_rows = [row for row in measured_rows if row["accepted"]]
    accepted_correct = sum(1 for row in accepted_rows if row["matched"])
    contract_correct = sum(
        1 for row in measured_rows if row["route_contract_matched"]
    )
    semantic_correct = sum(1 for row in measured_semantic if row["matched"])
    deterministic_correct = sum(1 for row in deterministic_rows if row["matched"])
    high_risk_skills = set(
        routing_config["quality_gate"].get("zero_false_positive_skills", [])
    )
    high_risk_false_positives = [
        row
        for row in measured_rows
        if row["actual_skill"] in high_risk_skills and not row["matched"]
    ]
    minimum = float(dataset["minimum_top1_accuracy"])
    minimum_accepted_precision = float(dataset["minimum_accepted_precision"])
    minimum_coverage = float(dataset["minimum_coverage"])
    minimum_route_contract_accuracy = float(
        dataset["minimum_route_contract_accuracy"]
    )
    accuracy = correct / len(measured_rows) if measured_rows else 0.0
    accepted_precision = (
        accepted_correct / len(accepted_rows) if accepted_rows else 0.0
    )
    coverage = len(accepted_rows) / len(rows) if rows else 0.0
    route_contract_accuracy = (
        contract_correct / len(measured_rows) if measured_rows else 0.0
    )
    complete = len(measured_rows) == len(rows)
    return {
        "schema_version": 2,
        "metric": "top1_owner_accuracy",
        "minimum": minimum,
        "minimum_accepted_precision": minimum_accepted_precision,
        "minimum_coverage": minimum_coverage,
        "minimum_route_contract_accuracy": minimum_route_contract_accuracy,
        "case_count": len(rows),
        "measured_count": len(measured_rows),
        "semantic_case_count": len(semantic_rows),
        "semantic_measured_count": len(measured_semantic),
        "semantic_model_case_count": len(semantic_model_rows),
        "semantic_model_measured_count": len(measured_semantic_model),
        "semantic_correct_count": semantic_correct,
        "semantic_accuracy": (
            semantic_correct / len(measured_semantic) if measured_semantic else None
        ),
        "deterministic_accuracy": (
            deterministic_correct / len(deterministic_rows) if deterministic_rows else 0.0
        ),
        "correct_count": correct,
        "accuracy": accuracy,
        "accepted_count": len(accepted_rows),
        "accepted_correct_count": accepted_correct,
        "accepted_precision": accepted_precision,
        "coverage": coverage,
        "route_contract_correct_count": contract_correct,
        "route_contract_accuracy": route_contract_accuracy,
        "complete": complete,
        "high_risk_false_positive_count": len(high_risk_false_positives),
        "passed": (
            complete
            and accuracy >= minimum
            and accepted_precision >= minimum_accepted_precision
            and coverage >= minimum_coverage
            and route_contract_accuracy >= minimum_route_contract_accuracy
            and not high_risk_false_positives
        ),
        "rows": rows,
    }


def build_semantic_prompt(
    dataset: dict[str, Any],
    index_path: Path,
    routing_config: dict[str, Any] | None = None,
) -> str:
    config = routing_config or load_config(DEFAULT_CONFIG, index_path)
    index = json.loads(index_path.read_text(encoding="utf-8"))
    skills = [
        {
            "name": item.get("name"),
            "project": item.get("project"),
            "description": item.get("description"),
        }
        for item in index.get("skills", [])
        if item.get("name") != "wb-model"
    ]
    model_cases = semantic_model_cases(dataset, config)
    cases = [
        {
            "id": case["id"],
            "input": case["input"],
            "project_id": case.get("project_id"),
        }
        for case in model_cases
    ]
    production_contract = (
        DEFAULT_SEMANTIC_PROMPT.read_text(encoding="utf-8")
        .partition("## 当前可用 Skills")[0]
        .strip()
    )
    thresholds = {
        "model_accept_threshold": config["_semantic_routing"][
            "model_accept_threshold"
        ],
        "minimum_margin": config["_semantic_routing"]["minimum_margin"],
    }
    production_contract = production_contract.replace(
        "{{ROUTING_POLICY_JSON}}",
        json.dumps(
            {
                **thresholds,
                "zero_false_positive_skills": sorted(
                    config["quality_gate"]["zero_false_positive_skills"]
                ),
            },
            ensure_ascii=False,
            indent=2,
        ),
    )
    return (
        "你是 wb-chat 的离线路由评测器。对每个 case 独立应用下面的生产路由契约；"
        "case 之间没有连续上下文。只输出 JSON，不加 code fence。\n\n"
        "## 生产路由契约\n\n"
        + production_contract
        + "\n\n## 接受阈值\n"
        + json.dumps(thresholds, ensure_ascii=False, indent=2)
        + "\n\n## 批量输出契约\n\n"
        "输出 schema_version=2；每项严格包含 id、skill、decision、score、"
        "runner_up_skill、runner_up_score。decision 只能是 route、answer、clarify；"
        "route 选择非 wb-chat owner，answer/clarify 选择 wb-chat。"
        "score 是相对匹配度；没有 runner-up 时两个 runner-up 字段都为 null。\n\n"
        "输出示例结构: {\"schema_version\":2,\"predictions\":["
        "{\"id\":\"...\",\"skill\":\"...\",\"decision\":\"route\","
        "\"score\":0.93,\"runner_up_skill\":\"wb-chat\",\"runner_up_score\":0.20}]}\n\n"
        "## Skills\n"
        + json.dumps(skills, ensure_ascii=False, indent=2)
        + "\n\n## Cases\n"
        + json.dumps(cases, ensure_ascii=False, indent=2)
        + "\n"
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Evaluate Workbench skill routing accuracy")
    parser.add_argument("--cases", default=str(DEFAULT_CASES))
    parser.add_argument("--config", default=str(DEFAULT_CONFIG))
    parser.add_argument("--index", default=str(DEFAULT_INDEX))
    parser.add_argument("--predictions")
    parser.add_argument("--print-semantic-prompt", action="store_true")
    parser.add_argument("--require-semantic", action="store_true")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args(argv)
    try:
        cases = load_cases(Path(args.cases).expanduser().resolve())
        index_path = Path(args.index).expanduser().resolve()
        config = load_config(Path(args.config).expanduser().resolve(), index_path)
        if args.print_semantic_prompt:
            print(build_semantic_prompt(cases, index_path, config))
            return 0
        threshold_pairs = {
            "minimum_top1_accuracy": "minimum",
            "minimum_accepted_precision": "minimum_accepted_precision",
            "minimum_coverage": "minimum_coverage",
            "minimum_route_contract_accuracy": "minimum_route_contract_accuracy",
        }
        for dataset_key, config_key in threshold_pairs.items():
            if float(cases[dataset_key]) != float(config["quality_gate"][config_key]):
                raise RoutingEvaluationError(
                    f"评测集 {dataset_key} 与 apps/agent/conf/skill-routing.yaml "
                    f"quality_gate.{config_key} 不一致"
                )
        predictions = load_predictions(
            Path(args.predictions).expanduser().resolve() if args.predictions else None
        )
        result = evaluate(cases, config, predictions=predictions)
        if args.json:
            print(json.dumps(result, ensure_ascii=False, indent=2))
        else:
            status = "PASS" if result["passed"] else ("PARTIAL" if not result["complete"] else "FAIL")
            print(
                f"{status}: top1_owner_accuracy={result['accuracy']:.2%}, "
                f"measured={result['measured_count']}/{result['case_count']}, "
                f"semantic={result['semantic_measured_count']}/{result['semantic_case_count']}, "
                f"minimum={result['minimum']:.2%}"
            )
            print(
                f"  accepted_precision={result['accepted_precision']:.2%}, "
                f"coverage={result['coverage']:.2%}, "
                f"route_contract_accuracy={result['route_contract_accuracy']:.2%}"
            )
            if result["semantic_accuracy"] is not None:
                print(f"  semantic_accuracy={result['semantic_accuracy']:.2%}")
            for row in result["rows"]:
                if row["measured"] and not row["matched"]:
                    print(
                        f"  MISS {row['id']}: expected={row['expected_skill']} "
                        f"actual={row['actual_skill']}"
                    )
        if args.require_semantic and not result["complete"]:
            return 2
        return 0 if (result["passed"] or not args.require_semantic) else 1
    except (RoutingEvaluationError, ValueError, OSError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

